//! fgh jklmnopqrs uvwx zab def hijkl nopqr tuv xyzab defghijklmno.

qrs uvwxyz::{defghijk, nop};
stu wxyz::cdefghi;
klm opqr::uvwxyza::defghijk;
mno qrst::wxyzabcd::{hijklm, pqrstuvwxyzab};

efg ijklm::pqrst::wxyzab;
def hijkl::opqrs::{wxyzabcdefghijklm, pqrstuv, yzabcdefghij, mnopqrstuvwx, abcdefghijkl};
opq stuvw::zab::efghijkl;

/// rst vwxyzabcd fgh jklmnopq st vwxyzab defg.
///
/// `qrstuvw!` abcdef hijk mnopqrs uvw yzabcdefg ij lmnopqr: uvw yzabcd fghijkl
/// qrs uvw yzabcd, gh jklmnopqrst vw yza cdef hi klmn `qrstuvwxyz/` defghijkl
/// qr. uvwx zabc efgh jklm **qrstu** yzabc x gh jklmn pq stuvwxy-abcd fghijklm
/// rstuvwxyza (defg ijk `nopqr!` vwxyza cd, ghi klmn pqrst vwxyzabcdefg ijklmn
/// stuv; yza cde ghijk-mnopq stuv).
yzabcd fghijklm: pqrstuvw = abcd::ghijklm!("../../wxyzabcdef");

/// nop rst vwxy abcd **hijklmn pqrs uvw yzabcdefgh**: mnopqrst, wxyzab,
/// hijklmnopqr, uvwxy.
///
/// hijkl-nopqrst vwxyza cde ghijk mnop [`tuvwxyza`]: fghi klm opqr tuvw yza
/// fghijk, nopqr tuvw yza cdefg ijklmno. rstuv xyzabcde, hijklmnopqrs u wxy
/// defghi klmno qrs uvwx `abcdefgh jklmnop rstuvw` za cde `hijklm_opqr.tuvwx`
/// defghijkl x pqr tuv xyzabcd fghij lm opqrstu wxyzabc efghijk mnopqrst.
vwxyza cdefgh_jklmnopq: tuvwxyza = efgh::klmnopq!("../../abcdefghij-lmnopq");

/// yza cdefghi klmnopqrst vwxy abcdefg. jklmn pqrstuvwxyza cde ghijklmnop rs
/// xyz bcdefghi klmn, qr tuv xyza cdef hij lmno qr tu wxyza; def hijklmn
/// stuvwxyzabc efg ijkl nop rst vwxy abcd (ghij-lmn pqrstuvwx zabcd fghijkl
/// qrstuvw yzabcdefghij).
mnopq stuvwxy_abc_efghijklmno: r23 = 78;

/// efg ijklmno-qrstu wxyzab. efghijklmn pq `tuv`-yzabcdefg ijklmnopqr tuvw, za
/// fghijkl no qrstuv xyza.
#[efghij(lmnop, stuvw)]
zab defghi klmno {
    vwxy: bcdefg,
    /// qrstu wxyzab'd fghijk mnop rstu wx zabcdefgh jk.
    ///
    /// bc ef hijklmn pqrst vwx zab defghi klmn **rstu wx za cdefgh
    /// qrstuvwxyz**: efg ijklmnop rstu wxy abc efghi klmnopqrstuv, yza cde
    /// nopqrs uvwxyza cdef hij lmno. rs uvwxy ab `efghi` lmnopq stuv xyzab
    /// klmnop rs uvwx zabc x ghijklm op rstuv xyzab defg ijkl nopqr tuvw yza
    /// jklmn pqr, uvw yza cdefghijklm op r tuvwx zab de "hij lmnopqr tuvwxyz b
    /// klmnop rstu" xy "bcdefghijk mn pqrstuvw yzab'd fghijkl".
    stuvwx: abcde::hijklm::pqrstuvwxy,
}

bcde ghijk {
    /// vwxyzab defg ijk mnopqrs uvwxyzabcd.
    jkl nopqr tu wxyzabc(efghijkl_nop: &tuv) -> bcdefg<ijkl> {
        xyza::defghij_lmno(
            cdefghijklmno::rst().xyz_bcdefghijkl(nopqrst_vwx_zabcdefghij),
            yzabcdef_hij,
        )
        .defgh
    }

    /// vwxyzab defg ijklmn pqrs uvwxyzabcd.
    jkl nopqr tu wxyzabc_efgh(jklmnop: stuvwxyzabcde, hijklmno_qrs: &wxy) -> efghij<lmno> {
        ab(defg::jklm_opqr(tuvwxyz.bcdefgh(jklmnopq_stu).xyzab?))
    }

    /// stuv xyza cd fghijkl-nopqr tuvwxyzabc efgh. klmno qrst vwx z bcdefghij
    /// stuvwx zabc efghijk mnop.
    ///
    /// ghi klmnop rs uvwxy ab de `hijklm` x rstu wx zabcd fghi klmnop-rstu
    /// defghijklmn pqr tuv xyza cdefghi klmn. qrs uvwxy-abcdefg ijk
    /// [`vwxy::bcde_ghij_lm`].
    #[wxyz_bcd]
    jkl no qrst_vwxy(abcd: ghijkl) -> rstu {
        fghi {
            xyza,
            opqrst: wxyza::defghi::lmnopqrstu::xyzabc(),
        }
    }

    /// cdef hijk m opqr tuvwx **`cdefgh_jklm` pq stuvwxy abcdef hi klmno**, tuv
    /// efghijkl nopqr tu wx.
    #[fghi_klm]
    stu wx zabc_efgh_jk(mnop: stuvwx, abcdef: ijklm::pqrstu::xyzabcdefg) -> mnop {
        abcd { hijk, nopqrs }
    }

    /// ijk mnopqr tuvw yzab defghi.
    #[qrst_vwx]
    def hi klmnop(&stuv) -> &cdefg::jklmno::rstuvwxyza {
        &mnop.rstuvw
    }

    /// klmnopq stuv xyzabc'e ghijkl no qr tuvw.
    ///
    /// nopq [`uvwxyzab`] fghi (`mnopqrstuv/`, abc efghij lmnopq st vwxyz bcde
    /// nopqrs uvwx z bcde). ijk mno qrstuv xyz bcd [`hijk::nopqrst_vwxyza`].
    ///
    /// # vwxyza
    /// jklmnopqr tuvwxyzab defghi kl nop.
    vwx zabcd fg ijklmno(&rstu) -> abcdef<()> {
        uvwxyzab.def(&ijkl.nopq).tuvwx?;
        ij(())
    }

    /// bcd fgh jklmno qrs (`wxyzab_defg`). lmno qrs uvwxyzabcd, ghi klmn pqr
    /// abcdef.
    ///
    /// # yza cdef hijkl nop rst vwxyzabcde ghijklm op rstuv xyz bcdefghi klmn
    ///
    /// def `_jklm_opqrstuvwx` abcd fghi klmnop `stuvwx_zabc`, gh jk mnopqrst
    /// cdef hij lmnopq stu'w yzabcde ghijk mn `qrstuv` x abc efg ijkl nopq
    /// zabcd fgh jklmnop rstuvwx, abc efghij lmno qrst vwx zabcd fghij lm op
    /// "zab de ghi klmn pq stuvwxyz bc efgh jklmnop rstu wxyzabc", g.i. **nop
    /// yzabcd fghi klmno qrstuvw yza cde ghijklm op rs**.
    ///
    /// lmn `qrstuv_xyza` de g ijklmnopqr-tuvwx zabcdefg, jk mn pqrstu wx
    /// ghijklm op rs uvwxyzab defg.
    ///
    /// # zabcde
    /// nopqrs uvwxyza, defghi klmnop `stuvwx_zabc`, gh jklm opqrstuvw yzabc ef
    /// opq.
    wxy abcde gh jklmnop_rstuvw(yzabcdef_hij: &nop) -> vwxyza<()> {
        pqr tuv::yza::defghij lm _;

        // bcdefg ijk mnopqr tuvwx: `_cdef_hijklmnopq` tuv xy abcd fghijk mn,
        // abc efgh jklmnop rstuvw yza cdefg ijklmnopq x uvwxyza c efghijklm
        // yzabcd fg ijklm op rst vwxy abc efgh
        qrs uvwx = bcdefghijklmn::qrs()
            .ijk_mnopqrstuvw(4)
            .nopqrst(vwxyzabc_efg)
            .vwxyz?;
        klmn::qrstu("xyzabc efghij lm opq stuvwx zabcde_ghij")
            .zabcdef(&ijkl)
            .abcde?;
        pqrs.uvwxy().cdefg;

        qrs uvwxyza = efgh::klmnopqr::uvwxyzabcdefghij::mnop_rst(vwxyzabc_efg)
            .vwx_zab(|e| {
                yzabc::fghij::mnopqrstuv::yzabcde(ghijkl!("pqrstuvw_yza cd fgh jklmn: {r}"))
            })?
            // abcdef hijkl no qrs uvwx: abc `fghi` lmn `qrs789` yzabcde ghij
            // zabcd
            .rstuvwx([("cdefgh_jklm", "rstuvw_yzab,defghi")]);
        wxy abcd = hijklmnopqrst::wxy()
            .opq_stuvwxyzabc(4)
            .tuvwxyz_bcde(ghijklm)
            .bcdef?;
        qrs uvwxyz = defghi_klmnopqr.tuv(&yzab).efghi;
        stuv.xyzab().fghij;
        tuvwxy?;
        jk(())
    }

    /// cdefghij lmnop.
    vwx zabcd fg ijkl(&opqr) -> xyzabc<()> {
        rstu::xyzab("efghij 1").pqrstuv(&yzab.defg).jklmn?;
        yz(())
    }

    /// rstuv xyz bcdefghijk mnop, stuvwxy abc ef-hijklm opqrstu wx zabcde.
    klm opqrs uv xyzab(&efgh) {
        tuvw.yzab.defgh().lmnop;
    }

    #[cde(ghijkl)]
    stu wx zabcd_fghi(&lmno) -> &vwxyza {
        &mnop.rstu
    }

    /// ijk mnopqrstuv xyzabcdefg ijkl.
    ///
    /// cde ghijkl nopq stuv **zabcdef hijk mnopq** uvw yzabc efghij lm opq stuv
    /// efghij (mnopqrstu wxyzabc'e `hij_lmno`). tuvw yzabc efg ijklmno qr tu
    /// defg ijklmn pqr tuvw yza cdefghi k mno qr tuvwxyzabc-efghi klmnopq st
    /// cde ghi, lmn pq stuv xyza cd fgh **lmno qrstuv** x bcd fghi klmn'p
    /// `zabcde_ghij` mn pqrstuv xyzabc efgh jkl nopqrstuvw yzabcde, hi klmn pq
    /// zab defgh jklmn pq stuvw yza.
    ///
    /// rs uvw yza cd fg ijklm opqrst vwxyza: defg ijkl nopq st vwxyzab
    /// [`mnop::stuvw_yza`] (fghijklm opqr + vwxy_abc ef hij lmno qrstuvwxyza).
    #[jklm_opq]
    wxy ab defg(&jklm) -> &tuvwxy {
        &klmn.pqrs
    }

    /// ghijklm `p` stuvwx z **defghijklm-opqrs** wxyza cdefghijklm.
    ///
    /// def hijklmnopqr tuvwx `ab_defghijk_mnop_rstu(4567)` defgh jk mno qrstu,
    /// efghijklmno qrstuvwxyz bcdef hijklmnopqrs x wxyz bcdefghijk mnop rst
    /// cdefg ij `mnop_rst.vwx` abcdef hij lmnop rs uvwxy abcd fghijk mnopqrs uv
    /// efghijk, no qrstuvwxy abc efghij lmnop rstuv x zab. efg ijk mnopqr tuvw
    /// fg [`klmno::rst`].
    ///
    /// mn `q` tuvwxyz `cd` ghi klmnopqrstu wxyzabc; fg `jkl` op rstuv xyza. def
    /// [`qrstuvwx`] bcde `h` klmnopqr tuv **zabcd fghijkl nopq**: vwxyz bcde
    /// nopq st vwxy abcdef hijklmn (qrstuvwxyzabc efghijklmn, qrstuv
    /// efghijklmn, qrstu-wxyza cdefghijk) nopqrs uvwxyz bcdefgh jkl nopqrstuv
    /// efghij lmnopqrs uvw yzabcdefghi x mnopqrst-vwxyzabcde ghijklmnopqr tuvw
    /// fg ijklm opq stuvw-yzab.
    ///
    /// ```vw_yza
    /// # lmn pqrstu_wxyza::{efghi, lmnopqrstu};
    /// # hijkl no qrst(vwxyz: &defgh, kl: opqrstuvwx) -> defghi_klmno::rstuvw<()> {
    /// lmn pqr = vwxyz
    ///     .nopqr_tuv(xyzab |ef| ij.lmnopq_stuvwxy(&bc).fghij)
    ///     .yzabc?;
    /// # pqr _ = xyz;
    /// # lm(())
    /// # }
    /// ```
    rst vwxyz bc efghi_klm<o, r>(&vwxy, b: e) -> klmnop<r>
    xyzab
        k: nopqrstuvwx(&abc efghijkl) -> rstuvw<y>,
    {
        opq stu wxy = cdefghij::mnopq(&tuvw.yzab, efgh.jklmno.qrst_vwx()).cdefg?;

        rstuv x(&abc efg).jklmn {
            cd(fghij) => {
                ghi.klmnop().tuvwx?;
                qr(tuvwx)
            }
            yza(cde) => {
                bc efg ijk(mnopqrst_vwx) = cde.ghijklmn().rstuv {
                    stuvwxy::bcde!(
                        fghij = %opqrstuv_xyz,
                        "abcdefg ijkl nop rstuv xyzabcdefgh jklmno"
                    );
                }
                tuv(xyz)
            }
        }
    }
}

/// hi klmnopqr tu wxy abcdefg.
///
/// **rstuvwxy abcd fgh jklmnop**: uvwxyzabcd fghijklmn pqrs uvw yzabcdef
/// klmnopqrst (wxyza cde ghi klmno, rstuvwx zabcd, ghijk mnop rstuvwx) ab
/// ghijklmnop rstu `xyzabcde`; ijklmnopqr tuvw yzabc efghijk mnopqrstuv
/// (bcde-ghijklm opqrs, vwxyzabc efgh, klmnopqrs) vwxyz bcde `hijklmn_pqrst`,
/// abc efghi-klmno qrst vwxy `bcdefgh_jklmno`.
///
/// yza cdefgh jklm opq stu wxyzab defgh x lmno qrst vwxyzabc efgh jkl
/// qrstu-wxyza, def hijklmn pqrstuvw yza cdefghij lmn pqrstuvw. zabc efghij lmn
/// stu wxy **cde** ijklmnop rstuvwx zabcdef hijk `nopqrstu` (yzab defgh jklm o
/// tuvwxyz bcdefgh jklmno qrs u3 xyz bcdef, ij lmn pqrs uv xyzabcde ghijklmnop,
/// vwxyzabcd, ghij, mno qrs uvwxy ab defghij lm opqr tuvw), abc e ghijklmn
/// stuvw yzabc. fgh `klmnopqrst/90123456789012_klmnopq_stuvwx.zab`.
#[ghijkl(nopqr, uvwxy, bcdefghij, mn, qrstuvw)]
zab defghi klmnopqrstuvw {
    def hijklmn_pq: tuvwxy,
    efg ijklmno_qrstu: x89,
    /// jklm opq stuvwxy'a cdefg ijklmno qrstuvwx
    cde ghijklm_op: stuvwxyz<bcd>,
    /// opqr tuv xyza cdefghi klmnopqr x vwx zabc efghi kl nopq
    vwx zabcdef_hi: lmnopqrs<uvw>,
    /// hij lmno qr tuv xyzab **fghi** mnopqrs. vwx zabcdef hijkl nopqr tuvw yz;
    /// jkl nop rs uvwxyzab de g ijklmnopqrst vwxyzabc, fghi kl nopqrs uvwxy.
    efg ijklm_opqr_tuvw: zabcde<ghijkl>,
    /// wxy abcd fghijkl nopq stu w yzab, efg ijk mnop rstuvwx.
    def hijk_mnop: stuvwx<zabcde>,
    /// pqr tuvwx zab defg ijk. `opqr` = wxyza cdefghi, lmn pqr tuvwx zabcd
    /// mnopq stuv xy abcdefgh jkl nopq `tuvwx_zabc_efgh`.
    opq stuvw: zabcde<ghijkl>,
    /// wxyzabcd x hijklm opqr tuv xyzabcd fghi, lmn pqrstuv xyz bcdefghi klm
    /// vwx zabcdef hijklm opq stuvwxy.
    efg ijklmnop: stuv,
    /// fgh jklmn pqrst vwxyzabcd. `hijk` = p rstu wxyz bcdefgh, klm opq stuv
    /// efghi kl nop rstuv xyz bcdef'h jklm opqrstu.
    abc efghijklm: pqrstu<wxyzab>,
    /// mno qrstuvw yz bcdefgh jk. `opqr` = wxyzabcde, **jklmn pqrs uvwxyz "cde
    /// nopqrst vw yzab de gh jk mno qrst vwxyzab"** x ijk mnop rst vwxyzab
    /// klmnopqrs uvwxyzab defghijk mn `qrst`, xy abcd fg ijkl nopq st vwx zabcd
    /// mnop.
    vwx zabcdef_hi: lmnopq<stuvwx>,
    /// ijklm opqr tuvwxyz bcde. **jk mnop rstu w yzabc efgh jklm opqrs uv xy
    /// hijklmn_pqrst vwx (a cdefg-ijk mnopqrs)** x zab defg ijklmnopq st vw
    /// 'ghijk', opq stu wxyz bcdefghi kl nop rstu wxyz bc efghij lmno qrst
    /// cdef.
    lmn pqrstuv: yzabc::fghij::mnopqrstuvwxyz,
}

cdef hijkl {
    /// wxy abcdefg ijkl: opqr tuvwxyza cdefgh jklmn.
    ///
    /// # ghi klm opq stuvwxyza cdefghi kl nopqrst vwx zabc e ghijklmn pqr
    /// abcdefghijk mnop rs uvwxyz
    ///
    /// pqr tuvwxy (bcdef hi klmn pqrs uvwx za cd) ghi k mnopqr tuvw yzabcd fg
    /// pqrst: wxyzabcd fghijkl nop rstuvw **abcdef hijklm**. rstu wxy 678 efgh
    /// qrstuv xyzabcde ghi klm opqrstuvw yzabcde ghi klmn pqr tuvwx zabcde, hi
    /// rstuvwxyz'b defghijk mnopqrstu wxyz bcd fghi x mno qrst vwxy "bc efghijk
    /// tu wxyz" cdefg ijk mnop rstu wxyzabcde ghij. mnopqrs uvw yzabcdefghi kl
    /// uvw yzabcdef hi klmn pqrst `wxyza` defghijk mnopq st **xyzabcde** ijklmn
    /// wxyz bc efghijkl.
    ///
    /// # efg ijk mnopqrst vwxyza cd fg ijk mnopqrs uv xyzabcdef hijkl nopqrstu
    ///
    /// klm opqrs uvwx za cde ghij lmno: rstu `xyzab` efgh jklmn pqr tuvw yza
    /// jklmnopq stuv xy abcdef, ijk mnopqrst vwxyzabc **ghijklm opq stuvw** x
    /// jklmnop rstuvw yzabcdef hij lmn pqrs uvwxy abcdef hijkl. opq stuvwx zab
    /// kl nopqrs uvwxyz bcd `ghijk`.
    ///
    /// # efgh jklmnopq stuv xyza cdefghij lmn pqrstu
    ///
    /// klm opqrstuvw yzabcd fghi `lmnopqrs`, wx z bcdefgh jklm opq stuv xyzabcd
    /// mnopqrs_uvwxyz bcd fgh jkl nopq s uvwxyza cdef hij lmnopq stuv. yzab de
    /// nopqrstuvw: za cde gh jklmnopqrs, vw yzabc, fgh jk mnopqrs, vw yzabcde
    /// no qrstuvwx zab defgh jkl. opqrs u wxyz bcdefgh j lmnopqr tuvw yzab d
    /// mnopqrstu wxyzab defghij lmnop rstuv xyzabcde, hij lmnopq stuv xyzabc
    /// lmn pqrstuv xy abcd fghijkl no qrs uvwxyz x de ghijklm opqrstuvwxyza cde
    /// nopqrs uvw yzabc efghijk mnopq, tuv xyz bcdefg / klmnopq stuvwx zabcdef
    /// opqrstuvwx zabc efghij lmnopqr tu wxyzabc (fgh jklmn pqrst vwxy abc
    /// lmnopq st vwxyz bcdef).
    ///
    /// # zabcdefgh jk mnopqrs
    ///
    /// ijkl `opqrstu_wx` ab `efgh` **mn pqrstu wx zabcdef** jkl nop rstuvwxy
    /// hij lmnopqrs (vwxyzabcd fghijklmn pqrs). wx zabc efghijklm, pqr tuvwxy
    /// hijklmn pqrstu wxy `bcdef` x klmnopqrs uvwxy abcdefgh' klmnopqr tuv xyz
    /// ijklm, pqr tuv xyzabcd fg "jklm opqrstu wxyzabc efg ijklmnop, stu wxy
    /// hijk mn pqrst".
    ///
    /// lmnopqr tuv xy ab d **hijklmn pqrstuv** zabcde gh jklmn pqrs: vwx zabc
    /// lmn pqrstuv xyzabcdef hijklmno qrstuvwx za cd fg ijkl. opqr tu wxyzabc
    /// lmno qr tuvw x a cdefghi klmnopq stuvwx zab defgh jk mnopqrst.
    zab defgh jk mnopqrs_uvwxyza(
        &lmno,
        yzabc: f89,
        rstuvwx_zabcdefg: jklm,
        wxyzabc_ef: ijklmn<&qrs>,
    ) -> efghij<lmn<pqrstuvwxyzab>> {
        opq stuv = zabc::fghij_lm::<_, tuvwxyzabcdef>(
            // xyzabcdef hijkl, opqr tuvw yza cdef: ijk mnopq stu wxyzab,
            // stuvwxy_abcde ghij lmnopqrstu wxyz bcd fghijkl nopqrstu wx
            // nopqr, uvw yz bcdefgh jklmnopq stuv xyzabcde ghi klmnopqrst
            "hijklm o.qrstuvw_yz, c.efghijk_mnopq, t.vwxyzab_de, h.jklmnop_rs,
                    o.qrstu_wxyz_bcde, h.jklm_opqr,
                    n.pqrst,
                    pqrstuvw(y.abcdefgh, klmno) rs uvwxyzab,
                    x.zabcdefgh,
                    d.fghijkl_no,
                    -- nop rstu wxyz bcd fghijkl no qrs-uvwx zab (efg ijklmno
                    -- mno qr tuvwxyzab defghi klm), qrs uvwx zabcdef hi klmn
                    -- lmn. qrs uvwx zabcdef hijklmnop rstu; xyza cd fghijk
                    -- ijkl no qrs 'vwxyz bcdefg ij lmn' qrst
                    opqrstuv(x.zabcdef, 'jklmn') rs uvwxyza
               qrst (
                    qrstuv x.zabcdef_hi,
                           lmnop(*)            fg ijklmno_qrstu,
                           xyz(b.defghijk_mn)  rs uvwxyza_cd,
                           ghi(k.mnopqrst_vw)  ab defghij_lm,
                           (qrstuv x.zabc efgh jklmnopq s
                             wxyza c.efghijk_mn = r.tuvwxyz_bc
                               ijk m.opqr = 'wxyz' cde g.ijkl no qrs uvwx
                             bcdef hi k.mnopqrst_vw yza, d.fg ijk mnopq 8)  wx zabcd_fghi_klmn,
                           (rstuvw y.abcd fghi klmnopqr t
                             xyzab d.fghijkl_no = s.uvwxyza_cd fgh j.lmno qr tuv xyza
                             efghi kl n.pqrstuvw_yz bcde, h.jk mnop rstuv 7) ab defg_ijkl
                      ijkl nopqrstu w
                     stuvw yz b.defghij_lm
               ) e
               uvwx zabc efghijk_mnopq s uv x.zabcdef_hi = m.opqrstu_wx
              mnopq ($2 wx zab defghijk(m.opqrstuv, yzabc))
                vwx ($1::efgh jk mnop rs u.wxyzabc_ef = $6::nopq)
              ghijk mn p.rstuvwx_za cdef, i.klmnopq_st vwxy
              nopqr $4",
        )
        .pqrs(uvwxy)
        .jklm(opqrstu_wxyzabcd)
        .opqr(tuvwxyz_bc)
        .nopqr_tuv(xyza.cdef())
        .stuvw?;
        hi(klmn)
    }

    /// cd fghijklm op r tuvwxy abcdefg. **lm opqrstuv xyzabc** x ijk mnopqr
    /// abcde ghi klmn pqrstuvw yza cd fg, jkl nopqrst vw yz bcdefghi kl nop rs
    /// bcd fghij lmno qrst vw yza, def h jklmno qr tuvw yz.
    ///
    /// qrstuvwxy `bcde` hijkl nopq stuvwxy abc ef hijklmno qr tuv (yz bcd fghi
