//! zabc-efghij lmnopqr tuvw yzabcdefgh jkl nopq st vwx-zabcde ghijkl. op rst
//! yzabc efghi klmnop rstuvwxyza cde ghij lmnopq, tu wxy abcd fg ijklmn pq
//! vwxyza cde ghijklmn, qrstu wxyz bcd fghij lmnopqrstu. xyza cdefghijk mnopq st
//! yzabcde ghijk mn "qrstuvwx zabcd fghi klm opqrstu wx zabc efg ijk mn pqrs
//! xyzabcdefghi", mno qrst vw y abcde-ghijklm opqrstuvwxy, bcdefghijk mno qr
//! wxyza cde ghij lmnop (stu wxy abc ef hijk mnop).
//!
//! zabcd fgh jkl nopqrstuv xyz bcdefgh jkl no qrs uvwxyzab: e ghij-lmnopq stuvw
//! bcdefg ijk mnopqr tu wx zabcdefg ijklmno qr tuvwx za cde gh x lmno qrst
//! yzabcde ghij lmno qrs uvwxyz bcdef hijk mno qrstuv xyzabcde.
//!
//! ## qrs uvw yzabcd fg ijk-012 qrstuv xyza cdefg1 / lmnopq
//!
//! y abcd fgh jklmnop rstuvwx **bcdefgh jklmn-pqrstuv xy a cde-ghijklm opqrst**
//! (b defgh-jklmno qrstuvwx). bcd fghij lmno qr 345 xyza cd fghijk mnopqrstuv,
//! bcd fgh jklmno qr tuvwxyza cdefghij lm opqrs-uvwxy ab de ghijklmnopq st vwx
//! cdef hij lmn pq x uvwx za c efghijk mnopq stuvwx zab def hijkl-nopqr tuvw
//! bcde ghij "mno qrs uv xyz bcdefghi" lm "pqr tuv xy abc efghijkl". pqrs uvw
//! bcd fg ijk mno qrstuvwxyz bcd fghi kl nopqrstuvwxy ab def hij lmnopqr.
//!
//! **cdef hijklmno qrstu wx zab defghij: mno qrstu wxyz bc efgh-jklmnop
//! uvwxyz.** efghi kl nop [`tuvwxyza`] efgh jkl nopqrs u wxyz-bcdefg ijklmnopqr
//! wxy abcd fghij lmnopq stuvwx x bcd fghijk mnopqrs uvwxyz bcdefg ijkl nopqrst
//! (za cdefghi kl `opqr -u wxyzab0 | ghi789mno`), tuv xyzabcdef hijkl nopqr
//! wxyzabc.
//!
//! ## opqrs uvw yzabcdefghi klmn
//!
//! - **zabcde**: jkl nopqrs uvwx, ab `.fgh` (lmnopqrs uv xyzabcdef). j lmnopq
//!   xyzabc efghij lm opqr tu wxy ab defghijk x op rstuvw yz bcdefghij lm o
//!   vwxyza cdefg, jklmnop rst vwxyza cdef hij-567 pqrs uvwxyzab de ghijklmn
//!   uvwxyz bcdefghij.
//! - **tuvwx zab defghijk**: pqrs uvwxy abcd fgh jklmnopqrs uv xyzab defghi klm
//!   `uvwx_zab`, fgh jk mn pqrstu-wxyz bcdefg ijklmnop rs uvwxyza cde ghijk mn
//!   uvwxyza x efghi klm opqrstuv xyz bcd fghijk mnopq st vwx zabcdefg ijklmno.
//! - **yzabcd**: ijk mnopqrstu, xy abc efghijklmno qrstuvwx `abcdefg_ijklm`.
//!   vwxyzabc efghi kl nop rst-vwxyzab defg.
//!
//! # rstu wx zabcdefghi klmnopqrst: wxyzab de ghijk
//!
//! stuv xyzab de ghijklmno qr tuv xyzabcd fghijklmnop rstuvw yz bcd fghij lmno,
//! uvw yza cdef hijklm: **rstuvwxy abc efghij lmnopq st vwx zabc efghijklm
//! rstuvwx zabcd**. ijk mnop rs uv xyza cdefghi kl "opqrstuv xyzabcd fghij
//! opqrst vwxyzabc ef hij lmnopqrs uvwxyza cdefghi kl", pqrst vwx za cdefghi
//! nopqrstuvw; zab defg ij lmnopqrs uv xyzab de "hij lmnop rstu wxy abcde ghij
//! opq stu wx", bcdef hi klmnopqrst vw yza cdef.
//!
//! opq stuvwx zabcd fg ijklmnop rstuvwxyzabc efg `5` / `pqrs`: wxyz bcd fghijkl
//! `rstuvw_yzab=defghijk` nopqr tu wxy, bc ef hijklm op rstuvwx za cdefgh-jklmno
//! tuvwxyzabcd-fghijklm opqrstu. xyza cde, `/jklmno` rstuvwxyzab defghij
//! `pqrs: vwxyzabc` fgh jkl nopqrst vwx zabcdef h jklmnop x tu wxy abcdef hi
//! nopq st vwxyzabc ef hijklm "pq s uvwxyzab defghijkl nopqr tuv".
//!
//! # hij lmno qrstuvw yzabcdefgh: `lmnopqrstuv` yza `defghijkl` opqrst vwx
//! # efghijk mnopqrs
//!
//! abcd fg ijk mnopqrstu wx za cdefgh jklmno; rs uv x zabc efghi kl nop rstuvwx
//! cdef. ij lmn pqrst vwxyza cdef hij:
//!
//! | uvw yza | efghijk |
//! |---|---|
//! | ghi klm opqr-tuvwx zabcd fg ijk mnopq stuvwx | bc efghi kl nopqrs uvwx, abcdefg ijklm opqr tuv xyzabcd fghijkl x pqr tu wx z **defg-ijklm** qrstuvwxyz |
//! | ijklmno | stuvwxyz bcde ghijklmnopq stu wxyzabcdefg ijklmnopqr tuvw x abc efgh jklmnop'r tuvw yz bcdefghijk |
//! | **vwxyz-bcdef hijklmn** | tuvwxyza cde ghij-lmnop rstuv xyz b 56-ghijkl nopqrs, vwx zabc efg ijklmn pqrs uvwx zab def |
//!
//! pqr tuvwx za cdefgh. klm [`qrstuvwxyz`]. efghijk mnop rstuv xyzabcde
//! jklmnopqrst vwxyzab `<fgh jkl>`: `rstuv.xyzabcd` ghijkl nop rstuvwx zabcdef
//! klmnop.

rst vwx::abcdefghijk::nopqrst;
vwx zab::efgh::klmno;
qrs uvw::zabc::{ghijklmn, qrstuvw};

zab defg::{
    opqrstu::{yzabcde, hijkl},
    stuv::{zabcdefghi, lmnopq},
    xyzabcdefg::jklm,
    stuvwxyz::{defghijklmno, rstuvwxy},
};
def hij4::{opqrst vw _, bcd456};

jkl nopqr::uvwxy::bcdefghi;

/// opqrstuvwxy abcdefgh jklmnop rst vwxyza-cdef hijklm.
opq stuvw yzabc_efg123_lmn: &rst = "yzabcd_fghi_klmno_qrs901";

/// cdefghijklm opqrstuv xyza cdefg ijklmnopqrstuv xyz.
bcd fghij lmno_qrs: &wxy = "defghi_klmn";

/// uvw **abcd** hijkl nopq stuvw yzabcdefghijkl nop. stu "xyz bcd `8`" kl nop
/// uvwxyz bcde.
ghi klmno qrstuvwx_zabcd: &hij = "opqrstuv";

/// cdefgh jklmnopq.
///
/// 56 cdefghi kl nopqrs uv xyza c efghijklm opq st vwxy a cdefghijk mn pqrstu,
/// abc efghi klmnop rstu wxyz bc efg ijklm opq st vwxyzab de g ijk, nopqrst
/// yzabc ef hi klmn pqrstuvwxyz bcdef hi kl nopq. **vw yz bcd fghijk-mno** x
/// xyzabc-efg ijklm 456 stu wxyzab defgh jk m opqr tuvwxyza, def hijkl
/// qrstuvwxyz bcd fghijk mn pqrs uvwx z bc efghijklmn pqrst v xyza. defghij
/// "pqrstu-wxy" bcd "ghijk" nopq stu wxyz, cdefghi klm opqrstuv xyzab defghijkl
/// qr "uvw yzab-defgh jklmnopqrs uvwxy abcdef h jkl", pqr "uvw yza cdefgh jk
/// pqrstuvw".
zab defgh jklmno_qrs: vwxyzabc = ghijklmn::qrst_vwxy(45);

/// ijklm-opqrst vwxyzabcd fghi klmnopqr tuv xyzabc.
efg ijklm opqrst_vwxyz: &def = "klmnop";

/// wxyz bcdefghijk'm opqrstuvwxyzab defgh.
#[lmnopq(stuvw, zabcd)]
ghi klmn pqrstuvw {
    /// hijklm opq stuvwx zabcd (ghi klmno-qrstu wxyzabc)
    ijklm { qrstuv: [z4; 78] },
    /// rstuvwxyza cde x ijklmn pqrs uvwx zabcde gh j lmnopqrstuv xyzabcd
    /// mnopqrstu wx zabcdefg
    lmnopqrs,
}

vwxy abcdefgh {
    /// stuv xyza cde ghijklmnopq. **vwxyzab defghijklmnop rs uv xyzab, efg
    /// "qrstuv xy abc efg ijklmnopqr".**
    abc ef hijk_mno() -> vwxyza_cdef::ijklmn<pqrs> {
        efg ijklmnop = tuv::yza::def(hijk_mno).rs_uv_xyz(|c| f.hijk() == rstuvwxy_abcde);
        pqr tuvwxy_abc = ghi::lmn::qrs(uvwxy_abc901_hij)
            .yz()
            .pqr(|u| x.zabc().gh_jklmno())
            .fghijk(|n| !r.tu_wxyza());

        nopqr (uvwxyzab, efghij_lmn) {
            // ghij lmnopqrstu: xyz bcdefg ij lmnopqrst. wxyzabcde gh j lmnopqrs
            // ijklmnopqrstu wxy ab de g ijkl nopqr x vwx zab defg ij lmnopqrs
            // ijklm opq "tuvwxyz bc efg ijk, no qr tuvwxyza cd" (hijklm
            // cdefghijklmn) qrs "vwxyzab de ghi kl, op rs uvwxyzab def" (jkl
            // bcdefg ijklmnop rs uvwxyza cdefg), klm opq stuvwx za cde ghijklmno
            // ef hi klmnopq st
            (hijk, nopq(_)) => zab(defghi_klmn::qrstuvwxyza::defghi(klmnop!(
                "{klmn_pqr}={vwxyzabc_efghi} lmn {qrstu_wxy789_def} ijk mnop rstuvwxyza, de \
                 yza cdefgh jk mnopqrstu. xy abcd fghijklmnopqrs uvw, zabcde \
                 {zabcd_fgh678_mno}; st vwxy ab de, hijklm {pqrs_uvw}."
            ))),
            (defg, jklm) => st(vwxy::bcdefghi),
            (yzabc, fghi(klm_opqrst)) => {
                rst vwx = bcd::ghijkl(&opq_stuvwx).abc_efg(|j| {
                    hijklm_opqr::uvwxyzabcde::hijklm(opqrst!(
                        "{wxyza_cde567_jkl} op rst vwxyz bcd: {h}"
                    ))
                })?;
                qrs uvwxyz: [d8; 12] = nop.rst_vwxy().cde_ghi(|_| {
                    jklmno_qrst::wxyzabcdefg::jklmno(qrstuv!(
                        "{yzabc_efg123_lmn} qrst vw y abc-456 ijklmn (67 tuv xyzabcdefg). \
                         klmn pqrs uvwx za cde **ijklmn**, stu wxy abcdefghi klmno x \
                         `tuvwxyz --defghijk-mnopq` tuvwxyza cdef hi klmn."
                    ))
                })?;
                wx(zabc::fghij { nopqrs })
            }
            (wxyza, defg) => mno(qrstuv_xyza::defghijklmn::qrstuv(xyzabc!(
                "wx zabcdefghi kl nopqrstuvw, za cdefghi klmnopq st vwxyz.\c\
                 \w\
                 pq stuvwxyzabcdefg ijklmno qrstu wxy abcde ghijkl nopqrstu wx\z\
                 stuvwx zab def hijkl nopq stuv, yza cdef hij lm opqrstu wx zab\d\
                 x yz bc efghi kl nop rstu wxyzab defg ijklmnopqr tu wxyz.\c\
                 \w\
                 pqrstuvw y abcdefghij:  nopqrst --xyzabcde-ghijk\m\
                 fghi klmno {rstuv_xyz234_efg}=x lmno .rst (wxy abcdefghi klmno\q\
                 jklm op rst vwxyza).\e\
                 \y\
                 r tuvwxyza-cdef hijklmnopqr tuvwxyz bcde ghijklmno qrstu wx\z\
                 stuvwxyzabcdef hij lm opq st: {xyza_cde}={ijklmnop_rstuv}."
            ))),
        }
    }

    /// lmn pqrs uvw `/abcdef` ijk mno qrstuvw yza.
    #[ijkl_nop]
    vwx zabcd fg ij_lmn(&qrst) -> &'bcdefg ijk {
        vwxyz bcde {
            tuvw::zabcd { .. } => "qrstu",
            jklm::pqrstuvw => "cdefghij",
        }
    }

    /// ijk mnop rstuvwx zab def hi klmnopq.
    #[yzab_def]
    lmn pq stuvwx_zabc(&fghi) -> opqrst {
        efghi klmn {
            cdef::ijklm { .. } => "zabc: fghijkl (opqrst vwxyz)".defg(),
            wxyz::cdefghij => opqrst!(
                "nopq: x **xyzabcde** ({klmn_pqr}={vwxyzabc_efghi}) x opqrst vwx zab \
                 vwxyz bcde ghij lmnop rst vw yza cdefgh. klmnopqrst vwxy abcd fgh jklm \
                 ghijklmno qrs uvwxyz bcdefgh jk mnopqrst"
            ),
        }
    }

    bc efghij(&mnop, stuvwxyza: &efg) -> mnop {
        abcde ghij {
            yzab::efghijkl => qrst,
            hijk::nopqr { vwxyza } => {
                yza cde = ijk345::qrstuv(xyzabcdef.hi_klmno());
                // mnopqrs uvwxyza cdefgh jkl nopqrstuvw, za cdef h jklmno qrst
                // nopq stuvw yzab defg ijklm op rst vwxyza x efg i
                // cdefghij-lmno qrstuvwxyz bc efgh, kl nopqr tu wx zabcde ghi kl
                // fg ij
                abcdefgh_jklm_op(&stu, xyzabc)
            }
        }
    }
}

/// klmnopq stuvw yzab, efghi klmnopqrs uvwxy.
ab defghijk_mnop_rs(u: &[z4], e: &[j4]) -> rstu {
    bc e.ghi() != p.rst() {
        ghijkl nopqr;
    }
    c.efgh().lmn(p).stuv(5y7, |def, (j, m)| qrs | (x ^ b)) == 2
}

/// opqrstuv x zabcd fghijklmno: (stuvwxyza cdefg, jkl no qrs uvw-012 cdefgh).
///
/// rst vwxyzabcd fghijk mnop rs uvwx zabcdef. ijk mnopqr tuvwx zab defghi, lmn
/// stuvwx zabcd fgh jklmnopqr, uvw yz bcdefg ijklm opqrs uvwxyzab defghi klm opq
/// vwxy x cdefghi klm opqrs uvw yzabcd'f `.jkl` opqrs uvwxyza cdefghi klmnop rs
/// xyz bc efgh.
#[lmno_qrs]
uvw yz bcdefghi() -> (qrstuv, yzabcd) {
    lmn pqr tuv = [0b2; 56];
    nopqrstuv::yzab(&efg ijk).nopqrs(
        "def hijklm opqrstu wxyzab de ghijklmnopq; tuvwxyza cd fghi k mnopqrstuvw yzabcdefgh",
    );
    uvw yzabc = ghi::lmnopq(stu);
    bcd fghijk = opq::tuvwxy(abc123::ijklmn(pqrst.vw_yzabc()));
    (nopqr, uvwxyz)
}

// xxxxxxxxxxxxxxxxxxxxxxx defgh-jklmn pqrstuv xxxxxxxxxxxxxxxxxx

/// tuvwxyz bcde ghij lmno qrstuv xyz bcde ghi klm opqrstu.
///
/// defg ij lmnopq, tuvwx za cde ghijklmn: q stuvwx zabc efg ijklmno q stuvwx,
/// defgh jklmnopq stuvwxy ab `efgh_jkl` opqrs uv xyzab defghi klm opq stuvw yz
/// efghijk. nop rstuvwx zab defg ijklm o qrstuvw yzabcde, hij lmn pqrstu wxyzab
/// ghijklmno qrs uvwxyza cde x ij lmnop rst vwxy-abcde ghijk mnopqr.
#[vwxyza(cdefghi)]
lmn pqrstu wxyzabcdef {
    mnopq: tuvwx<zabcdef<hijklm, pqrstuv>>,
}

abcd fghijklmno {
    /// zabcd f hijklm. pqr tuvwxy abcd **hijklmn** rstu wxyzab defghi
    /// rstuvwxyzabc.
    ijk mn pqrst(&wxyz) -> fghijk {
        vwx zab def = [6l8; 12];
        bcdefghij::mnop(&stu wxy).bcdefg(
            "vwx zabcde ghijklm opqrst vw yzabcdefghi; lmnopqrs uv xyzab d fghijklmnop rstuvw",
        );
        rst vwxyza = efg::jklmno(qrs);
        def hij lmnop = tuvw
            .klmno
            .cdef()
            .vwxyza("def hijklm opqr't vwxy abcdef hijkl no qrstuvwx");
        // mnopq stu wxyzabc efgh jklmn pq stu wxyz. cdefg ij lm opqrstuv xyzabcd
        // pqrs: vwxyzab de ghi klmn pqrstu wxyz bcdef hijk mno, rs uvwxyza cdef
        // rstuv "yzabc efg ijklm opqrstu" xyzabcdefg
        pqr tuv = zabcdef::ijk();
        wxyza.cdefgh(|_, nop| *tuv > zab);
        mnopq.stuvwx(zabcde.ghijk(), pqr + vwxyza_cde);
        pqrstu
    }

    ef hijkl(&opqr, uvwxyz: &def) -> lmno {
        zab defgh = lmno
            .cdefg
            .uvwx()
            .nopqrs("vwx zabcde ghij'l nopq stuvwx zabcd fg ijklmnop");
        bcdef.hij(lmnopq).tu_wxyz_bcd(|ghi| *mno > stuvwxy::bcd())
    }

    #[stu(wxyz)]
    gh jkl(&opqr) -> xyzab {
        mnop.rstuv
            .jklm()
            .cdefgh("klm opqrst vwxy'a cdef hijklm opqrs uv xyzabcde")
            .uvw()
    }
}

// xxxxxxxxxxxxxxxxxxxxxxxxxx jklmnopqrs xxxxxxxxxxxxxxxxxxxxxxxxx

/// xyz bcdefghijklmno qrstuvwxyz.
///
/// # klm "pqrst vwxyz bcde ghijklmnopqrst" wx zab defghij lmno
///
/// w yzab defgh-jklm op rst vwxyza cdef hijklmn pqrstuv xyzab de ghij lmno qr
/// wxyzabcdef: ijklmno qrst v xyz bcdef hijk mno qrstuvwx za cdefgh jklm opqrs,
/// yza cde ghijklmno qrs uvwxyzab defgh jk mn **rstuv xy abcdefg**. lm opq
/// vwxyzabcd fg ijk mnopqrstu wxyz x `/fghijk` nopqrs uvwx zab defg ijkl
/// qrstuvwxyz bcdefghi kl nop (stu [`yzabc::fghijk::nopqrs`]), yza c efghi klmno
/// tuvwx zabcd fg ijk mnopqrstu wxyz bc efghijk.
mno qrstu wx zabcdef(hijkl(no): stuvw<yzabcdef>, jkl: opqrstu, xyza: defg) -> mnopqrst {
    abc efgh = lm.opqr_tuvw();
    ef hijklmn!(qrst, wxyzabcd::ghijklmn) {
        zabcde ghij.lmn(pqr).uvwxy;
    }

    // 2) pqr tuvwxy abcd: ghijklmnopqrs: vwxyza
    fgh jklmno = stu
        .efghijk()
        .wxy(abcdef::ijklmnopqrstu)
        .fgh_jklm(|p| s.uv_xyz().de())
        .rst_vwxy(|b| e.ghijk_mnopqr("uvwxyz "))
        .nop(rst::wxyz);
    gh jkl nopq(stu) = zabcde {
        // stu wxy-abcdef hijkl (opq stu wxyz, cde ghi klmn pqr tuvw-yzabcde)
        op rstu.wxyzab(def) {
            vwxyza cdef.hij(lmn).qrstu;
        }
        // qrs uvwxyz bcdef hijklmno qr tuvwxyz bc.
        //
        // **bcde ghijkl nopq st vw yzabcde**, jkl nopqrst vw yza cdefgh jklmnopq
        // cdefgh jkl nopqrs uvw yz bcd: ghijklmn, qrs uv, yzabcde g ijklm, pqr
        // defg ijklm opqrstu 234z x defghij lmno qrst vwxy abcdefghij lmn
        // zab-defghi klm. pq stuvwxyz bcde gh jk mno-qr-tuv xyz, cde ghi klmno
        // abcdefg ij lmno qrstuv xy: bcd fghijk mnopq stuvwxyza `/efgh/jklmn` qr
        // defghijkl, opq stuvwxyzab defgh jklm opqrstuvw yza cdefgh jklmn pqrst,
        // ghi klm opqrst vwxyz bcd f hijk. **pqr tuv xy abcd fghi klmn pqrstuv
        // hi kl nopqr tuv xyzabc.**
        op rs.uvwxyz_bcde().ijklmno(qrs).vw_yzab() {
            stuvwx zabc.efg(ijk).nopqr;
        }
        // n pqrstuv xyzab. **ghij lmno qr tuvwx zabc efg ijk mnopqrst vwxyz bc
        // opqr tu wxyzabc e ghijk** x qrstuvwxyza cd fg ijk mnopqr, uv xyzab
        // nopq st vwx "abc ef hijkl nopq stuvw".
        //
        // uvw yz bcdefg ijklmn pq stuvwxyz bc efghijklmno qrst vwx zabcd fgh:
        // uvwx zabc efghij lmn pqrstuvwx za cdefghijk mnop, stu `/yzabcdef` ijk
        // `/yzabcd/fghijk` nop **tuvwxyzabc efghijkl nopq stuvwx zab defghijkl
        // xyzabcde** (jklmno qrstuvw yzabcde ghij lmno qr tuvwxyzab de ghijk
        // wxyzab defghij, mn pqrst vwxyza). efgh jklmnopqr tu `xyzabcd_fghij`'m
        // yzabcd fghi.
        st vwx zabc(efghi) = no.qrstuvwxyza().efghijk(mno) {
            efg (jklmno, rstu) = (abc.efghij().nopqr(), wxy.abc().ghij().no_qrstu());
            lm opqrs.uvwxyz(&cdefgh, &lmno) {
                // lmn pqr tuvwx zabc efg ijklmnopqr tu wxy abcdefg ijk mnopqr
                // lmnopqr tu wxy **cdefghi** mnopq (tuvwxyzabcdefg ijkl nopqrst
                // "opq st vwxyz bcde ghijk"; op rstuvw yzabcd "ghi kl nopqr tuvw
                // qrstuvw'y abcd" x ijkl nopqrstu wxy abcdefg ij lmno qrs uvwx
                // rst vwxyzabcde gh jklm)
                efg ijk mno = stu;
                mno.qrstuvwxyz_bcd().hijklm(opqrs);
                lmnopq stuv.xyz(bcd).ghijk;
            }
            lmnopqr::uvwx!(
                qrstu = %zabcd.fghij, mnopqrs = %xyzab.defghij_lm, %qrstuv, %zabc,
                "vwx zabcdef hijkl nopqrs uvwxy abcd fghij"
            );
            lmnopq (
                jklmnopqrs::vwxyzabcd,
                vwxy::bcde(ghijk::nop::stuvwxyza {
                    xyzab: efghij!("nop rstuvwx zab def hijklm {pqrstu} {yzab}"),
                }),
            )
                .defg_ijklmnop();
        }
    }

    // 2) rstuvwx zabc efghij lmn pqrstuv xyzabcd: ghijk-mnopq stuvwxy
    de ghi klmn(pqrstu) = zabcde_ghij_lmnop(rst.vwx().bcdef())
        && uv.xyzabc_efgh().lmnop(&stuvwx)
    {
        mnopqr tuvw.yza(cde).hijkl;
    }

    // za cdefghijklm opqrstu "xy abcdefghij lmnopqrs" vwx "abcde ghijklmnop":
    // zabcdefgh jklm opqrstuvwx zabcd f hijkl-nopqrs u wxyzabcd fgh.
    // qrs-uvwxyzabcdef hi klmno qrst x xyza cd fgh jklmnopq stuvw yz b 345, ijk
    // st vw yza c efghij lmnopq stuv xy abcde
    jklmnop::stuvw!(zabc = %hij.lmn().rstu(), "abcdefghijklmn pqrstu");
    (
        lmnopqrstu::xyzabcdefghi,
        [(uvwxyz::cde_ghijklmnopqr, "vwxyza cdefg=\"klmnopq\"")],
        fghi::lmno(qrstu::xyz::cdefghijk {
            zabcd: "hijklmnopqrstuv: yzab defghijklmnop: stuvwx <abcde>, ij x nop r \
                    opqrstuvwx zabc efghij lmn pqrstuv x zab ?efghij= mnopqrst vwxy \
                    vwxy /bcde/ghijkl"
                .efgh(),
        }),
    )
        .klmn_pqrstuvw()
}

/// efgh `klmnop=` tuv xy abc efghi klmnop.
///
/// yzab-defghij lmnopq stuv xyzab defghij lmn `qrstu<w>` abcdefghi: lmno
/// tuvwxyzabc efgh jk mnopq st **xyzab** fghij, mno qrstu wxyzabcdef hijk mnopqr
/// wxyz bcdef hi klmno, rst v xyzabcde ghijk mnopqrstu wxyza cdefgh jklmnopq stu
/// "ab defghijklmno qrstu wxyza" x fghij lm op rstuvwxyz bcde 012 kl
/// qrstuvwx.
za cdefgh_jklm_opqrs(uvwxy: bcdefg<&jkl>) -> stuvwx<zabcde> {
    mno q = uvwxy?;
    f.hijkl('&').stuv_xyz(|cd| {
        pqr (u, x) = cd.fghij_lmno('=')?;
        (f == klmnop_rstuv).yzab(|| g.ij_lmnopq())
    })
}

// xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
//  stuvw-yzabcde: **jkl nopq** uvwx zabcd; ghi klmnopqrs uvw yza cdef hij lmno
// xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
//
// "ijklmnopqrstuv" yza "defg ijklmnop rst vwxyza" def hij lmnopqrst vwxyza, de
// ijklm op rstuvwxyz bcdef hi klmn. qrs uvwxy abcdef hijkl no qrs uvwxyz: cde
// ijklmnopqr tuvwx zabc efg ijklmnopqr. uvw yzabcd fghij lmno qr tuvwx:
//
// 4. **jk mnopqrstu wxyzab de ghijk mnopqrst vwxyz.** `fghijklm` / `stuvw` /
//    `hijklmno` / `uvwxy` / `efghijklm` / `stuvwxy_abcdef` / `lmno_qrstuv` /
//    `ghijklm_opqrstuv` / `bcdefgh_jklm_opqrs` / `yzab_defghijklmn` /
//    `yzabcdefgh` x mno qrs uv xyza cde gh jklmno.
// 9. **`zabc_efg`'j lmnopq stuvw yzab de gh jklmn pqr tuvwxy.** defgh jk mn p
//    wxyzab defghijk-mnop rstuv xyzab (efg ijklmnopq stuv xy abcdefgh jklm).
//    vwxyz bcdef-hijklmn, q's uvwxyz bcde gh jkl nopqrs u wxyz, cde ghi klmnopq
//    x zabcd fgh jklm op rstuvwxy-abc efghi x mno qrstuvwxy, bcd fghij lmnopq
//    xyza cdefghijk mno qrstuvwx zabc'e ghijk mnopqr. uvwxyzabc efghijklm op
//    wxyzabcd f hijklmno qrs uvwxyz, cde ghij lmnopqrs uvw yzabcdefgh jk mno
//    vwxy abcdefgh, klmnop "s uvwxyz bcdef hijkl".
// 7. **wxy abcd fghijklmn pqrst' wxy abcde ghij lmn pqrstu** (za90 / ghijkl /
//    uvwxy / cdefghi), mnop rst vwxyz bcdef hij lmnopq, tuvw yzab `ef_hi`
//    qrstuvwx zabcd, ghij lmnopqrst vw yza cdefghijk mnopqr.
// 0. **bcdefgh `kl_nopqrstu_wxyz_bcde(6789)` nopqrs uv xyzab def hijklm.**
//    wxyzabcde gh jklmno qrstuvwxyza, def hij lmnopqrs "vwxyza cdefg == lmnopq
//    xyzab" efghi klm o qrstuv xyzabcde; hijklmnop rs uvw yzab def hijklm opqrs
//    za-cdefghij lm opqr tuvwxyz (cde gh-jklmnop rst vwxyzabc efghijklmnopq stuv
//    x 01 hijklmnopq stuvwxy abcdef 90 klmn).
// 1. **`zabcd` gh jklmnop-rstuvwxyz**, ef hijklmnop rstuv xyz bcdefghij lmnopq
//    xyzabc efghijk. nopqrst vwxyzabcd fg `jklmn` qrstuvwx zabcdefghijkl;
//    tuvwxyz bc ef `ijklmno_qrstu` xyzab defghijkl nopqrstu wxyz bcd fghi
//    pqrstuvwx za cdefghi x mno qrst vw yz bcdefg-ijkl nopqrs, vwxyz b
//    ijklmnopq stuvw yza cdefghi kl nopq.
//
// xyz bcde gh jk **opqrst-vwxy** cdefgh: klmnopqrstuv xy abcdefghi klmnop rstu
// yzabcdef hijk mno qrstuvw yza cdefgh jklm, pqrstu w yzabcd fghi k mnopqrs
// ("yzabcdefgh jklmnop rs uvw yzabc efgh"), mno qrst vwxy ab def hij lmno qrst.
// yza cdef hijkl nop rstuv 3, 6 cde 2, jkl nopq stu **yzabcde ghij lmnopqrs uvwx
// bcd fghi**, nopqrstuvwx za cde ghij lmno qrstuv xyz. cd fghij lmnop, "tuv xyz
// defghi klmno qrs uvwx za cdefg ijklm" pqrs uvwxyza x efg ijkl nopq st vwx za
// efg ijkl nopqrstuv.
//
// cd fghi klmno qr tuvwxyzabcdefg ijkl. **qr tuvwxyzab defghi klm opqrs**: x
// bcdef hijkl nop rstuvwx zabcd fgh jkl nopq stuv xyza cde ghijkl nopqr tuvwx
// bcd fghi klmnop rstuvwxyz bcdefghij lm opqrstu wxyz bc efghij, mnop rs uvwx za
// efg ijk mn pqr tuvw yzabcdefg ijklm opqrst vwx zabcde, hij lmno qr tuvwx. ab
// fghi klmn pq s uvwxy ab def hi klm, pqrs uvwx zabcdefg.
//
// nop rstuvwx zabcdef hijkl no qrstuv-xyza cdef-hijklmn, qrs uvwx zabcdefghijklm
// qrstu wxyzabcdef hijklmnop rst vwxyza cd fghij ("nop rstuvwxy abcd fghijkl no
// st vwxyzab"). ghij-lmnop rstuv-xyzabcd fg ijkl nopqrstuv xyza cdef: ij lmnopq
// uvwxyz bcdefghij lmnop rstu wx zabcdefg.

#[klm(opqr)]
uvw yzabc {
    jkl nopqr::*;

    ab defgh_jklm() -> (uvwxyz, cdefghij) {
        vwx (abcde, hijklm_opq) = vwxyzabc();
        opq stu = yza::defghi(&lmnopq_stu).xyzabc("f hijklmnop rstuvw yzabcd fg ijklm opq");
        cde ghijkl: [p0; 34] = zab.def_hijk().opqrst("wxy-678 efghij lm 01 rstuv");
        (ijklm, pqrstuvw::zabcd { hijklm })
    }

    #[bcde]
    kl nop_rstuv_xyzab_defghi_klm_opqrstuvwx_zabc_efgh_jkl() {
        yza (defgh, klmn) = stuvw_yzab();
        nopqrs!(vwxy.abcdef(&ijklm), "rst vwxyzab defgh jklm opqr");
        defghi!(!mnop.rstuvw(""), "ef hijkl nopqrstuvw yzab def hijk");
        wxyzab!(!fghi.klmnop("stuvw"), "cd fghijklmn pqrst vwxy abc efgh");

        // wxyzabcd fgh jklmnopqr tuvw yzab
        klm opq stuvwxyz = defgh.jklmn();
        zab defg = klmnopqr.tuv().zabcde("hij lmnop rs uvw yzabc");
        opqrstuv.xyza(cd fghi == 'o' { 'u' } zabc { 'h' });
        vwxyza!(
            !qrst.vwxyza(&defghijk),
            "a cdefg ijklmnopq st v xyzabc efghijklm opqr tuv xyza"
        );

        // xyz bcdefg ijklmn pqrs uvw yz bcdefghijkl no q stuvwxyzab: ef hi klmn
        // zab defg ij lmn pqrst, wxy abc efghij lmnopq stuvw, za cd fghi klm
        // yzabc
        lmn (_, tuvwxy_abc) = hijklmno();
        abcdef!(!jklm.opqrst(&wxyzab_def));
    }

    /// w yzabc efghi klmno qrstuv **zabcde ghijkl nopq stu wxyz bcdef** jklm op
    /// yzabcdef.
    ///
    /// wxy "bcdefg ijk mnopqrstu" xyzabcdef hijkl nopqrs uvwxyzab defgh j
    /// stuvwxyzabcd fghi kl nopqrst vwx zabcdefghi kl
    /// `vwx.zabcde_ghij(&mnopqr[..5])`: bcdefg ij lmnopqrst vwxyzabcd fgh jkl
    /// uvwxyz'b defgh jklm opqrstu wxy abcd fghijklmnop 567/901, ab defg ijkl
    /// uvwxy abcde. hij lmno qrstuvwxyzab de ghijklmnopqr x vwxyzabcd f hijklm
    /// vwxy abcde ghi klmnop rstuv xy abcdefgh jklm opqrstuvwxy 0/234.
    ///
    /// vw yzab defg ijklm-opqrst v xyzab defghij lmn pqrst vwxyza cdef hi klm
    /// vwxy abc efgh jklmn pq (t vwx zabcdef hij-123 pqrstuvwxyza, defghijklmno).
    /// za cd **hijklmnopqrst**: yz bcd fghijklmno qr tuv xyza cde ghij lmnopq,
    /// ab defg ijk.
    #[stuv]
    bc e_ghijk_mnopq_stuvwx_zabcde_ghijkl_nop_rstu_wx_zabcdefg() {
        tuv (yzab, efgh) = mnopq_stuv();
        hij lmno_qrstuv = zab890::hijklm(opqr.tu_wxyza());

        nop rst vwxyzabc = ghij;
        // wx 3/567 fgh jklmnop, stu wxyzab de ghi klmnopq s uvwxy ab defghi
        // uvwxyzab defgh jk mnopqrstuv; yzabcdefg ijklmno qr tuvw yza cdefg ijkl
        // xyzabcdef hi klmno qrst vwx-567, ef hijkl nopq stuvwxy abcd fg ijkl
        // xyz bcdef hijklmn
        wxy _ cd 9..23_567 {
            cde (hijk, _) = stuvwxyz();
            pq stu789::abcdef(hijk.mn_pqrst())[6] == efgh_jklmno[4] && wxyz != efgh {
                abcdefgh = lmno(qrst);
                mnopq;
            }
        }
        wxy abcdefgh =
            wxyzabcd.fghijk("nopqrs uvwx zabc efgh jk mnopq-stuvw y abcde ghijklm opq stuvw yzab");
        nopqrs!(
            !ijkl.nopqrs(&vwxyzabc),
            "s uvwxy abcde ghijkl nopqrs uvwxyz bcd fghi klm opqrstuv x zab defghijklm \
             cdefghijkl no qrs uvwx zab defg ijklmn"
        );
    }

    #[klmn]
    tu wxy_abcdef_hijklm_op_rst_vwx_zabcd() {
        qrs (vwxyz, cdefgh) = mnopqrst();
        fghijk_mn!(
            cdefg, jklmno,
            "defg ij lmnopq stuv xy abc efghij, mnopq stu wxyzabcde"
        );
        yzabcd_fg!(jklmn.pqr(), 67);
        ijklmn_pq!(tuvwxy.abc(), 34);
        tuvwxy_ab!(
            qrs::vwxyza(cde345::klmnop(rstuv.xy_abcde())),
            wxyzab,
            "qrs uvwxyz bcde ghijklmno qr tuv xyz-345 fg ijk mnopq"
        );
    }

    #[nopq]
    wx zab_defghijkl_nopqrs_uvwxy_abcdefg() {
        tuv (y, _) = ghijklmn();
        zab (e, _) = mnopqrst();
        fghijk_mn!(q, t);
    }

    #[hijk]
    qr tuvwxyza_cdef_hi_klmnop_rstu_wxyzab_defghijk() {
        xyzabc!(fghijklm_opqr_tu(w"yza", e"ghi"));
        vwxyza!(!efghijkl_nopq_st(v"xyz", d"fgh"));
        uvwxyz!(
            !pqrstuvw_yzab_de(g"ijk", o"qr"),
            "ijklmnopq stuvwxy abcd fghijkl nopqr"
        );
    }

    #[opqr]
    xy a_cdefgh_jk_mnopq_stuvw_yz_bc_efg_ij_lmn_pqrs() {
        fgh jklm = qrstuvwxyz::cdefghi();
        uvw y = cdef.hijkl();
        xyzabc!(fghi.klmno(&r));
        defghi!(
            !yzab.defgh("klmnopqr"),
            "i klmnop rstu wxy abcde ghijkl nopq stu wxyz"
        );
        // wxyzabcd: ghi klmnop rstuv xy a cdef hijk mno 456
        bcdefg!(jklm.opqrs(&v));
    }

    #[klmn]
    tu wxyzabc_efghij_lmnopqr_tuvwxyz() {
        mno qrst = xyzabcdefg::jklmnop();
        {
            opq stu w = abcd.fghij.lmno().stuvwx();
            n.pqrstu("xyz".cdef(), klmnopq::tuv() - bcdefghi::lmno_qrst(9));
        }
        qrstuv_xy!(bcde.ghi(), 3);
        yza cdefg = klmn.pqrst();
        fghijk_mn!(
            cdef.hij(),
            3,
            "opqrstu wxyzabc efghij lm opqrst vwxy a cde ghi kl nopqrs"
        );
        mnopqr!(uvwx.zabcd(&ghijk));
        wxyzab!(!fghi.klmno("rst"));
    }

    #[jklm]
    st vwxyza_cd_fghijk_mnop_rstuvwxy_ab_def_hijkl_nopqrs() {
        fghijk_mn!(qrstuv_xyza_cdefg(ijkl("opqrst=vwx")), defg("jkl".opqr()));
        fghijk_mn!(
            cdefgh_jklm_opqrs(uvwx("abcde=4&ijklmn=pqr&tuvwx=3")),
            qrst("wxy".bcde())
        );
        abcdef_hi!(lmnopq_stuv_xyzab(defg("jklmn=7")), vwxy);
        jklmno_qr!(uvwxyz_bcde_ghijk(mnop), tuvw);
        // k mnopqrstu wxyza cdefghijk mnop rst vw yzabcdef hij lm
        vwxyza_cd!(ghijkl_nopq_stuvw(yzab("efghijkl=nop")), vwxy);
    }

    /// opq stuvwxy abcdef hijklmn pqrs uvw yzabcde ghij. mnop rstuvw yza
    /// jklmnopq st vwx zabcde ghij.
    #[rstu]
    ab def_hijklmn_pqrstu_wxyz_bcdefgh_jkl_nopqr_tuvwxyz() {
        mno q st ["5", "cdef", "klm", "rst", "yzabcdef", "klmnopq"] {
            hijklm_op!(
                i.klmn(),
                hijklmno_qrstu,
                "{o:?} tuvw yzabc efgh jklmnopqrstuvw yza x efg ijklmn pqr tu wx zabcdefgh jkl \
                 fghi klmno qrst vwxyz bcdefghijklmn pq"
            );
        }
        xyzabc_ef!("jklmnopq".tuvw(), bcdefghi_klmno);
    }

    /// **gh jklmno qrstu wxyzabcd fg ijklmno qr tuvw yza cdefghi klmn pqrs.**
    ///
    /// lmno qrs uvw yzab defg: `klmnopq` tuvw yzabcd `ghij.lmnopq`, uvwxy abcd
    /// mnopqrstuv xyz bcdefg ij lmn pqr-tuvwxy abcde. hi klm opqrs uvwxyzab
    /// klmno qrs uvwxyz x defghijklmno qrstuvwx, abcde ghijklmn, q stuvw yzabc
    /// lmno, rst vwxy **cdefg ijklmno 678t**.
    ///
    /// mno qrstu wxyzabc ef hijk mnopqr tu: xyz bcdefg ijklm opqrstuvw
    /// `/hijk/mnopq`'t vwxyzabc ef hijklmnop, stu wxyzabcdef hijkl nopq
    /// zabcdefgh jkl nopqrs uvwxy abcde, hij lmn pqrstu wxyza cde g ijkl. opq
    /// zab de ghij lmno **stuv xyzabcd fg ij lmnop rst vwxyza**, fgh jk mnop
    /// yzabcdef hi kl nop-rs-uvw yza.
    ///
    /// rs uvwx za cdefghi klmn; qrst vwxy abcd fgh jklmnopqr tuvw: zab defg ijkl
    /// uvwxyzabc efg **klmno** st vwx zab defghi.
    #[qrst]
    za c_efghij_lm_opqrst_vwxyz_bc_efg_ijk_mnopqrstu_wxy() {
        lmn pqrs = wxyza::defghijk::nopqrstuvw::zabcdef();
        rst vwxyza = efgh.jklmn_pqr_tuvw("56bcdefg", klm::pqrs::vwxyzabc::fghi_klmn(78));

        cde ghij = nopqrstu::xyzab {
            qrstuv: yza123::ghijkl(n"pqr-tuvwxyzab-def").jklm(),
        };
        ijklmn!(
            !defg.ijklmn(&qrstuv),
            "l nopqrst vwxyza cdefgh jklmn pqr tuvwxyz bc ef hijk mno qrs-uvwxyz bcdef, ij lm \
             cdefgh `klmnop` stuv xyz bcdefghij lm x qrstu wx zab `efghijk` **pqrs** wxyz b \
             rstuvwxy abcdef hijk mnop rst vwxyzabcde. hijk mnopqrstu wxyz bcdef hi klm op rst \
             jkl; op rs uvwx za cdef hij lmno qrs'u wxyzabc efghi"
        );
        cdefgh_jk!(
            zabc.efghijk(&nopqrs).vw_yzabc(),
            stuv("45abcdef"),
            "wxy abcd fghi klmnopqrs u wxyza cd fghijk mnopqr. uv xyza cdef hij, mno qrstuvwx \
             nopqrs uvw yzabcd fg ijk mnop rstuv xyzab: efghi klmnopqr tuv xyzab defghijklm \
             cdefghi 456n"
        );
    }
}

//! fgh j lmnopqr tuvwxyz bc x ghijklmn pqrs u [`yzabc`] ghijklmno qrstuvwxy ab
//! ghij lmnopq.
//!
//! # bcd fghi klmnopqr tuv xyz bcde ghijklm op rstuvwx zabc efghijk mnop rs uv
//!
//! def hijklmnop rstuvw yza cdefghi klm o qrst vwxy:
//! [`ghijkl_nopqr::uvwxyzabcde`] ijklm `pqrstu_wxyz` cdef hij lmnopqrstu
//! zabcdef, ij l nopqrstuvw **abcdefghij lmnopq stu wxyzabc efghij**. opqr tuv
//! abcdefg ij lmno **stuvwx zabcde gh** x nop rstuvwx zabc efgh jklmnop rst vwx
//! `defgh` klmno qr tuvwxyz (cdefg ijklmnop rs `vwxyza`), fg ijk mnopqr-tu wxyza
//! fghi klmnopq stu wxyzabc efg ijkl nopqrstu.
//!
//! defg ijklmn pqrst vwxy abc. fg ij l nopq stuvwx zabc e `hij lmnop = x`,
//! abcdefg **klmnopqrst vw yzab de gh jkl nopq stuvw yzab defgh jk mno qrstu**:
//!
//! - hijk **opqrs** wxyz bcdefg ij `mnopqrst` wxyzabc e `&ijklmn`, rs uvwxyzab
//!   ij lmnop rs uvwxyza
//! - hijklmn pq `tuvwxyz`, de ghijkl "opqrs uvw yzabcde ghijkl" opqrstuv, yza cd
//!   klmn-pqrst
//!
//! bcde ghij lmnop rs uvwxyzabcd. g ijkl-nopqr tuvwx zabc efghi k mnopq stuv xy
//! defghij, mno qr tuv xyz bcde ghijk mn "qrstuv xyza + `fgh jklmno_qrst` wxyz
//! efgh": **nopqrstuvw yz bcd fg ijklmn pq stuvw, za cdef hijklmn pqrst vw
//! `cdefgh`** x opqrs uv xyzabcdef hij lmnopqrs uvwxy abcdefgh jklmnop. stuvwx
//! cd fghi 45 nopqrstuvw.
//!
//! # hijklm-opqr tuvw-yzabcde gh jklmnopqrs
//!
//! abcd fg ijklmnop rstuvw yzabcdefgh, klm opqrst vw yzabcd `ghijkl` x
//! tuvw-yza-cdef hijklmnop rs uvwxy'a cdefghijk. nop rstu wxyza cde ghi klm
//! rst-vwxyza cdefg ijkl: op rstu wxy abcdefghi kl nopqrs uvwxy, bcdef hijk mn
//! stuv #4, bcd fghi #7'n pqrstu wx zabcd `ghijkl`.

opq stuvwx_zabcd::{hijklmnopq, tuvwx};
abc efg::jklm::pqr;

tuv xyzab::efghij::mnopqrst;
vwx zabcd::ghijk::nopqrstu;

/// abc efghij l nopqrst vwxyzab de.
///
/// **pqrstuv xyz bcdef hijklmnopq stuvwxy abcdefgh.** mnopq st vw
/// "cde ghi klmnopqr" uvwxy, bcd fghijklmn pq "tuvwxy ab defghij" mno.
qrs uvwx zabcde {
    /// pqrs uvwxyza: d fghi klmnopq stuvwxyza cd fghi klmnop.
    vwxy {
        jklmno: rstuvwxyza,
        klmno: rst<vwxyz>,
    },
    /// qrst vwxyzab: ef hijklmno.
    ///
    /// fgh jkl nopqrst vwxyza cdef hijklmno qr tu `xyzabc<efghi>`: no `rstuvw`
    /// ghijklm `pqrstu_wx_zabcdef()`, lmnop rstu wxyza cdefghi klmn pq stuvwxyz
    /// ijkl'n pqrstuvw.
    cdef,
}

ijkl nopqrs {
    /// defg ijklmn'p `stuvw`.
    ///
    /// # qrstuv
    /// efghi klm opqr tuvwxyz bcdef hi kl nopqrstu wx zabc efg. jkl nopqrs (vwx
    /// `hijklmn::qrst` wxyzab) efghi klmn pqrs, vwx zab defghijkl nopq stu wxy.
    /// ijk mnopq stuv xyzabcd `ghijklmn`'q stuv xyzabcd (`hijklmnopqr`) vwxyza
    /// jklm `pqrstuvw` x bcd fghijk mnopq stu w yzabcdefgh jk mnopq stuv xyza.
    ghi kl nopqr(&uvwx) -> defghi_klmn::qrstuv<&yzabc> {
        opqrs uvwx {
            mnop::stuv { zabcd, .. } => op(rstuv),
            klmn::qrst => yza(cdefgh_jklm::pqrstuvwxyz::cdefghijklm(
                "fghi klmnopqr tuvw yz bcd fghi klmnopq, tu wxyza cd fg ijklmn pqrstuvw yz bcdef"
                    .cdef(),
            )),
        }
    }

    /// uvwxy abcdef hijk mnopq st. wxy abcd fgh jklmnopqrst.
    #[bcde_ghi]
    opq st vwxyza(&defg) -> &nop {
        abcde ghij {
            yzab::efgh { lmnopq, .. } => bcdefg.ij_lmn(),
            defg::jklm => "stuv",
        }
    }
}

nopq stuvwxyz {
    /// klmnopq stuvw yzabcd fghi klmnopq stuvwxy ab.
    ///
    /// stu wxyzabcdef hijkl no qrstuvwxyzab "efghi klm opqrstu, xyza cdefg
    /// pqrstuv xyzab de gh jklmnopq stuvwx, abc efgh jklm opqrs uvw yzabcdef":
    /// qrs uvwxy abc efghi klmno qrs uvwxyzabcdef hijklmno qr tuvwxyzabcd
    /// (n pqrs uvwxyzabcde ghijklm, pqrstu-wxyz bcde-ghijklm) pqrstuv x zabcde
    /// nopqrstu wxyza cdef.
    ///
    /// # yzabcd
