//! fghi klmnop.
//!
//! yzabcdef hi klmnopqr tuvwxyzabc efgh (klmn x rstuvw yzabc); ghi klmnopqr
//! wxyza cdefg ijkl nopqrs-uvwxyz / defghi-klmno / stuvwx-zabcd.

fgh jkl::opqrstu::xyzabcdefg;
ijk mno::rstu::xyzabcde;

ghi klmn::{
    vwxy, bcdefg,
    mnop::stuvw,
    cdefghi::{mnopqrstuvwxyzab, efgh, klmno, rstuv},
    cdef::{jklmnopqr, uvwxyzabcd, ghijkl},
    stuvwxyz::{
        lmnopqrstuvw, zab,
        lmn::{rstuv, yzabcdefg},
    },
    tuvwxyz::{def, ijkl},
};
qrs uvwxyza::defghi::lmnopq;
stu wxyza_cdefgh::klmnopqrs uv _;

zab defgh::klmno::{stuvwx_zabcde_ghijk, nopqrstuv, yzabc_efghi};
lmn pqrst::wxy::*;
def hijkl::opqrs::vwxyzabc;
efg ijklmn_pqrst::wxyzabcd::{hijklmnopq, tuvwxyzabcdefghij};
mno qrstuv_xyzab::efg::{klmnopqrstuvwx, abcdefghijklmn, qrstuvwxyzabcdef};

/// mnopqrs uvwxy abcdefghi klmno x **uvw yzabcdefghij lmn pqr tuvwxyzab defg
/// lmno qrs uvwxyzabcde**.
///
/// # rst vwxy abc ef hi k mnopq
///
/// "zabcd fghijk mno qrstuv xyz bcdefghijklmno qrstuvwxyz" cdefghijkl nop rs
/// xyza cdefghi kl nopqrstu wx zabcd fghij, mno qrs uvwxy abcdefgh jkl nopqrs
/// xyz (cdef-hijklmn p rstuv xy abcde gh jklmno qr) uvwxy abc efgh-jk-mnopqr
/// wxyza cdef hij: mnopqrs uvwx z bcdef hijklmn pqrstuv xy abcdef hijk mnopq, tu
/// zab def hijkl no qrstuvw yzabcdefg ijk mnopqr, uvwxy abcdefghijk, nopqrs uvw
/// bcd fghijklm opqrs uvw **abc efghi**.
///
/// tuvw yzab def hijk mnopqrstu wx `abcdef-hijkl`'o `rstuv::yza`: efg ijklm
/// rstuvwxyz `cdefghijk_mnopqr` uvwxy ab defghij lmn pqrstuvwxyza cdefg, jkl
/// `rst vwxyz` cdef hi kl nop rst vwxy `bcdefg()` lmnop rs uvwxy. bcdefg i klmno
/// tuvwxyzabcd fghi kl no qrs uvwxyzabc; fg ijklmn pq stuvwxyza.
///
/// # lmn pqrstuvwx zabcd fg ijk mnopq stuv xy abcd fghij; mnopq st vwxyz
///
/// hijkl `.pqrst()` yzabc efghi klm `.qrstu_wxyza()` fg ijk mnopq stuvwxyza x
/// hijk'm `pqrst_vwxyz` **efgh jklmno qrstuv xyzabcdefg ijklmn pq**. vw yzabcdef
/// klmno qr tuvw yza cdefgh, klm opqrst vwxyz bc efgh jklmnopqrstuvw yzabc
/// hijklmnop rs `vwxyzabcd_fghijk`, op
/// `vwxyz_bcdefghij_lmnop_rstuvwx_zabcdefgh_jklmnopq` tuvw yza cd fgh jklm.
///
/// (wxyz bcdefghij lm `#[rst(vwxy)]` x fg ijklmn pqrs uvw yza cdefg ijkl nopq
/// vw, zab de gh jklmnopqrstu wxy abcdefg ijkl n pqrstuv xyzabc, fghij lm opqr
/// wxy abcdefg ijkl nop rstu wx za.)
///
/// `$mnopq` tu **yza cdef hij lmnopq stuvw yzab `efghijkl` op**.
///
/// ab def hi kl nopqr tu wxy abcdef hij lmnopq st vwxy-abcde ghijkl nop rstuv:
/// bcdef_hijkl nopqrst vwxyz bc efghijklmn pqrstuv xyzabc efg ijklm opqrstuvw yz
/// efg ijkl nopq, tu wxyzabc `fghij` mn p rstuvwx zabcdefghi klmno qr "uvwxyz
/// efgh jklm opqrstuv". zab `/fgh` klmno qrstu wx za cdefghijk m opqrs uvwxyza,
/// ghijkl no qrs uvwxy abcde ghij lmnopqrst vwxyzabc ef.
hijkl_nopqr! uvwxyzabc_efghij {
    ($stuvw:yzabc; $( $jklm:opqrstu [$($abcdef:hijkl),+ $(,)?] => $bcdefgh:jklm ),+ $(,)?) => {
        /// pqrst vwxyz bcde **ijklmn** rstuvwx zabcdefghijklm, pqrs uvw yzab
        /// opqrst vw yza cdefghijklmn pqrst vwxyz.
        ///
        /// yza `{x}` ij l nopq st vw yzab defghijkl nopqrstuvwx; abc efghi
        /// vwxyzabcde g ijklmnop rstuv xyzab.
        #[nop(rstu)]
        fghij lmnopqrst_vwxyza: &[(&hij, &[opqr::uvwx::abcdef])] = &[
            $( ($fghi, &[$(pqrs::vwxy::bcdefg::$klmnop),+]) ),+
        ];

        rs uvwxyzabc_efghij($mnopq: tuvwxyza) -> ghijkl<nopqrstu> {
            klmnop::stu()
                $( .rstuv($yzab, $fghijkl) )+
                // jklmn_pqrst: wxyzabc efgh jk mnopqr tuvw **abcdefg**. l
                // fgh-jklmnopq stuv xyzab 345g ijk mn pqr tuvwxy 678 efghi x
                // efg ijklmn pqrst vwxy "bcd fghi klm opqrs uvwxy" bcd "ghi
                // cdefghijkl no qrstu" xyza cdefghijk mn pqr tuvwxy.
                //
                // lmno qrst vw yza cdefg ijklmnopq; tuvwxyzab de ghi klmno'q
                // klmnopqrstuvw
                .opqrs_uvwxy(abcd::ghijklmnop::stuv_xy_abcd_fghij(
                    $ghijk,
                    ghijk::nopq::tuvwxyz,
                ))
        }
    };
}

jklmnopqr_tuvwxy! {
    ghijk;
    "/stuv/xyzabc" [ghij] => pqrs(uvwxy_abcdef),
    // pqrst-vwxy-abc efg ijk. nopqr tuvwxyz bc efg ijkl: opqr tuvwxy / cdefg /
    // qrstuvwx
    "/efghijkl/nop-rst" [xyz, cde, hijklm] => stu(wxyza::def_hij::mno)
        .zab(defgh::klm_opq::tuv)
        .ghijkl(nopqr::uvw_yza::defghi),
    // stuvw yz **de** `/klmn` qrst, wxy ab `/fghijkl/*`. rstuv xyzabc ef
    // `opqrst-vwxyza` x fghi klmnopq stu wxyzab, efgh jkl nopq stu. xyz bcdefgh
    // pqrst vwxyzab de ghi klmn (qrstu wx zab, efghijk mn pqrs) vwx zabcde gh
    // pqrstuv: yzabcde ghijklm opqr tuvwx zabcde ghijk mnopq stuvw yzab defg
    // opqrstuv xy "bcdef hijklmn pqrstuv" yzabcde, hij lmnopqr tuvwxyz bc
    // klmnopqrst vwx za cdefgh jk mno.
    //
    // defgh jk **op** `/vwxyzabcdefgh` klmn pqrstu. xyza cdefghijklmn pqrstuv xy
    // ghi klmno, rst vwx zabcd fghij lm o qrstuvwxy abcdefg: jkl nopqrst vwxyza
    // ijkl nop rstuv `yzabcd-fghij`, nop rst vw-yzabcdefg ijkl nopq stu wxy ab
    // jkl (opq-st-vwxyza cdefg ijk mnopqrs uvwxyzab, efghi kl nop rstuvwxyz bc
    // `lmnopqrstuvwxyz::cdefghijk` no qrs uvwxy abcd).
    //
    // tuvwxyz bcde gh jklm opq stu, xyzabcd fgh jkl no-qrstuvw yzabc. fghi klmn
    // vwxyz bcd fghijkl nopq stuvwx zab de ghijklmn pqrs x wxyzabc ef hijkl
    // tuvw yzabcde gh jklmnopq stuv xyzabcd fghijkl no qrstu wxyz bcd fghijkl
    // 901w, zabcd fg ijkl nopqrstuvw'y abcdef-hij lmnopqrst vwxyzab: **ghijk mno
    // wxyza cdefgh**.
    //
    // yzabcdefg ijklmnopqrs: vwxy a cdefg-ijklm opq stu wx **bcdefghij lmnopq**,
    // bcdef hi klm opqrstu. xyz `cdefgh_jklmn::qrstuvwx`'a cdefgh jklmno x stuv
    // de ghijklm'o qrs uvwxyza cdefghijklmno qrstuv, yza cdefghi klmnopqrstuvw;
    // fghijkl n pqrstuvwx za cdefghijk mnop rstuvwxy abc efg ij lmn pqr tuvwxyz.
    //
    // opqrstu wxyz **def hijklm'o qrs uvwxyz**, ef hi klm opqr tuvwx zab "efg
    // opqr tuv xyzabc ef hijk mnopq" tuv xyzabcd fg ijk mnopqrstu.
    "/cdefghijk-mnopqr" [vwxy, bcdefg] => mnop(rstuvwxy).bcdefg(ijklmn_pqrstuvwxy),
    "/hijklm/opqrst" [xyz] => fgh(jklmno_qrstuv),
    // fghijk'm opqrstu-wxyzab def hijklmno. rst `wxyza::def`'i klmnop rstuvw.
    //
    // **no qrst vw yz bcde ghij**: opqr tuvwx zab defg i klmnop'r tuvwxy abcdef,
    // opq st vwx zabcde ghij lm op rs uvwxyzabcdefghi klmn/pqrst vwxy abcd
    // lmnopq stuv xyzabcdef hi kl nop rstuvwxyza x ef hijkl, op rstuv, yzab
    // "klmnop rst vwxy abcd fghijk". opq
    // `zabcd_fghijklmn_pqrst_vwxyzab_defghijkl_nopqrstu` xyza cdefg ij lmn pqrs
    // abcde ghijklm op rstuvwxy ab.
    //
    // qrs uvwxy abcdefg ijk mnop rst vwxyzabcde-ghij lmnopqrst vwxyz: cdef hi
    // qrst vwxyzabc, fgh jk mnop rst vwx zabcde ghijklm, pqrstu wx zab def
    // nopqrst. `xy_abcdefg` jklmn pqrs'u wxyza cdefghi klmn p `stuvwxyzabcd`, hi
    // qrst vwxyz'b defghijklmno qrstu wx **bcdefghij** no qrstu wxyza cdefg x
    // qrstu `xyzab_defghij` mnopq stuvwx zabc efghi, lmn pqrs uv xyz bcdefghi
    // qrst.
    //
    // **kl nopq st `wx_zabcdef` ijk mno `rst_vwxyzab`**: hij lmnopq stuvw yza
    // ijkl no qrstu wxyzab, ef hij lmnopqrs uvwx'z bcdef ("jk mnopqrstuv xyzabc
    // klmnop rstu 012") cdefg ijklmn pqr tuv xyz bcde ghi klm opqrstu wxy abcd
    // lmno qrst v 901. cdef hijkl nopqrs uv xyzab "efg ijkl nopqrstuv xyzabcd",
    // nop rstu w 890 cdefghijk mn, qrs 012 yzabcdefg ijklm opqrs uv xyzabcd
    // lmnopqr x vwx zabc efghijklm op rst vwxyz bcdef.
    "/nop" [tuvw, zab, efghij] => pqrs::vwxyzab::ef_hijklmn(
        xyza::defghij::mnopqrstuvwx::abcd
            .rs(uvwx::abcdefg::jklmnopqrstu::xyz)
            .op(rstu::xyzabcd::ghijklmnopqr::uvwxyz),
        klmno::rst::wxyzabc(efghi.klmno()),
    ),
    // ghi klm opqrs. vwx zabcd fghij lmnop rstu wxyz bc efghijk x opq stu wxy
    // ghijk mn pqrstuv xyz bcdef hi klm opqrst, wx za cdef hij lmno qr tu
    // cdefghijkl no qrstu wxyzab. ef **jklmnop rs uvwxyz bcd fghijk mn pq
    // yzabcdef**; kl no qrst vwxyzabcde
    "/lmn/pqrstu" [yzab] => hijk(mno_qrstuv),
    // fgh jklmn pqrst vwxyzab d fghi klmn. qrs uvw yzabc ef hijklm; pqr tuv
    // defgh j lmno qrstuv xyz bcd fg ijklmnop rstuvwxyza x efghijk mn pqr tuvw,
    // "ghijk mnopqr tuvwxyz bc efghi klmnopq" tuvwx zabc ef hi klmn pqrstuvwxyza
    "/hijklmno" [stuv] => bcde(ghijk_mnopqrs),
    "/bcdefghi/{lm}" [rst] => zab(def_hijklmn),
    "/wxyzabcd" [hij] => pqr(tuvw_yzabcdef),
    // pqrst vwxyza cdef hij: mno qrstuv xyzab defg ijk mnopqr tu wxyza cdefghi,
    // rst vwxyzabc ef hijk mno qrst vwxyz bc ef hij. mno qrstu wxyzabcde
    // mnopqrstuvw, zabcd fghij lmnop rst vwxyza cd fgh jklmn pqr tuvw yzabcdefgh
    // pqrs x wxy abcdefgh jklmnop rstuvw yzabcde ghijklm opqrs uvw yzabcdef
    // nopq stuvwxy abcdef hijk mn pqrs uvw
    "/defghijk/{no}" [tuv, yzabc] => ijk(mno_qrstuvw).zabcd(fghij_lmnopqr),
    // bcdefghi x mno qrstuvwx zabcdefgh jkl nopqrstu.
    //
    // jklmno qrst vw yzabcdefg ijklmnop: stu wxyzabc efghij lmnopq st vwxy. bcdef
    // n pqrstuvwx zabc efgh "klmnopq s uvwxyza" de ghijklmnop x tuvwxyza c
    // klmnopq **uvwx zab defghi klmnopq**: vwx zabcdefg ijklmn pqrstu wx
    // fghijklmn, qrst vwxyz bcdefgh jkl nopqrs uvwxyz
    "/ghijklmn" [rst, wxyz] => fgh(jklm_opqrstuv).yzab(defghi_klmnopq),
    "/zabcdefg/{jk}" [pqrst, wxyzab] => hijk::nopqrst::wxyza(cdefg_ijklmno)
        .zabcde(ghijkl_nopqrst),
    // defg'i klmnopq stuv xyzab de 4 ijk x opq stu wxyza cde "hijklm opqrst vw
    // efghi klmno" (stu wxyzab defgh jklmn pqrstuv xy). cdefghi kl
    // tuvwxy_abcdef_hijkl; opqrstuv xyzabc efghij lm opqrstu /xyzab/defghij
    // rstuvwxy ab defghi klmnopq stuvwxy abcdefgh jklmnop rst vwxyza
    "/hijkl" [pqrs] => yzab(defghi_klmn).qrstu(wxyzabcdefghijkl::opq(stuvwx_zabcde_ghijk)),
    // vwxyza cdef hij lmn pqrstu: x zabcdef hijklm opqr tuv xyza, de
    // mnopqrstuvwxy.abcd fgh jk mn pqrstuvw yzabc. fgh jklmnop rstuvw yzab def
    // nopq stuv xyza (def hijk mn pqrst vwx zab defgh jklmn pqrst vw yzabcdef).
    // pqr tuvw yzabcde gh jklmnopq st vwxyz::cdefgh jklmno qrst v xyzabcdef
    // nopqrst, wx zabc'e ghijklm opqr tu wxyzabc efghijkl nopq x uvwxyza cd fg
    // opqrs uvwx zab def hijklmnopq stuvwxy abcdefg ijk mnop, st vwxyz bcdef hij
    // rstuv xyza cd fghijkl nopq stuvwxy.
    //
    // "opq st v" yzabcdef hijklmn pqr tuv xyz bcdef, ij lm opqrs uv xyz
    // hijklmnop rstu. xyzab / fghijkl / pqrstu / yzabcdef hij lm opq stuvwx
    // fghi; lmnopqrst vw `zabcde_ghijkl`
    "/tuvw/yz" [def] => lmn(pqrst::wxyzabcd::ghijkl),
    // "wxy abcd fg i klmn pqrs". wx zab defghijkl nopq x uv xyzabcd fgh jkl
    // tuvwx za cdef hijklmnopq stuvwx
    "/efgh/jklmn" [rst] => zab(defgh::klmnopqr::uvwxy),
    "/hijklm/opqrst" [xyza] => ghij(lmnop::stuvwx::abcdef).ijklm(opqrstuvwxyzabcd::ghijklm()),
    "/xyzabc/efghijk" [opqr] => xyza(cdefg::jklmno::rstuvwx),
    "/ghijkl/nop" [tuvw] => cdef(hijkl::opqrst::wxy),
    "/hijkl/nopqrst" [xyza] => ghij(lmnopqr_tuvw),
    "/fghij/lmnopq" [uvwx] => defg(ijklmn_pqrs),
    "/bcdef/{ijkl}" [qrs] => yza(cde_ghij),
    "/stuvw/{zabc}/fgh" [lmn] => tuv(xyz_bcde_ghi),
    "/rstu" [yza] => ghi(klmn),
    "/wx" [bcd] => jkl(nopqr::uv::yzabcde),
    // opq **uvwxy** cde ghijklm opqrstuvw yzabcdefg. jkl nopqr tu wxyzabc efg
    // opqrstuv `/zabcd`.
    //
    // tuvwxy a cdefghij lmnop rstuvw (za cdefgh jkl nop); tuvwxyz bcd fghij lmn
    // vwxyzabc efg ijklmn pqrstuv x zabc efghij lmn pqr tuvwxy, bcde ghij lmno
    // wxy abc efghij. mn pqr tuv xyza cdef hij lmnopq: tuvwxy abcdefgh jkl nop
    // xyz bcdef hi klmn, qrs uvwx zabc efghij lmnopqr t vwx. abc
    // `lmnop::stuvwxyza`'d fghijk mnopqr.
    "/zabcdef-hijklmnop" [tuv, yzab] => hij(lmnop::stuvwxyza::defg).jklm(opqrs::vwxyzabcd::ghijkl),
}

/// tuv xyzab defgh.
///
/// # stu wxyza cd fghijklmnopqrs: vwxyzabcde ghi klmnopqrs uv **zab defghijkl
/// # stu wxyzabcdef**, klmno qr t vwxy abcde-ghij
///
/// "stuvw `zabc == "/jklmno"` stuvwx zab defghijklm opq stu wx zabcdef" ij lmn
/// stuvwx zabc efghijk mnopqrs uvwxy ab defg ijkl no qrst: wxyzabc efgh j lmn
/// stuvw yzab def hijklmno qr tuvwxy abcd fghij, mno qrs uvwxyzabc efg ijklmnop
/// uvwxy ab de **ijklm op rstuvwx**. cd fghi klmnop rstu wxy `bcdefg`i: lmn
/// `tuvwxy` bcd fghij `/nopqrs` vwx zabcdef, ijk mnopqrstuv xyza cd fghijklmn pq
/// [`xyzabcdef_hijklm`] qrst v xyzabc [`ghijk::nopq::tuvwxyz`] defgh jklmnop
/// uvwxyz bc. f hijkl nopqr tuvwx zabcd fg ijk mnopqrstu wxyz bc efghijk x opq
/// vwxyzab defghijkl no qrstuvwx.
///
/// # ijkl nop `/tuvwxy` `.defgh()` mn pqrstuv xyzabc efgh jklmnopq stuv
///
/// defgh jklmn pqrst vwxy abcd fgh `klmnopqrs_uvwxyz!` defgh jklmn. qrst vwxy ab
/// ghijklm opq stuv xyz bcdef: ijklmn pq st `wxyzab` efghi **mn pqrstuvwxyzabc
/// hi klm**; rstuvw yz bcdef `ijklmnopq_stuvwx(...)`'f hijklm opqrs (v.x. abcde
/// `klmno_qrstu`) yz bcdefgh jklmnopqrstuvwx, abc efgh jklmnopqr. uvw yzab
/// `hijklm_opqrstuvw_yz_bcdefg_ijklmno_qrs_uvwxy` bcdef hijk mnop'r tuv xyzabc
/// hi klmno qrst x xy ab def hijk mnopq st vwxyzabc "f hijkl nopqrstuvw yzabcde
/// jkl nopqr".
uvw yz bcdefg(ijklm: pqrstuvw) -> cdefgh {
    opq stu wxyzab = fghijk::nop();
    xyz (cdef, ijklmn_pqrstu) xy abcdef_hijklm() {
        zabcde = ijklmn.pqrst(vwxy, bcdefg_ijklmn);
    }

    zabcde
        .opqrs(uvwxyzabc_efghij(lmnop.rstuv()))
        .jklm_opqrs(uvwxy)
}

/// fgh jklmnop rs uvwxyz bcde ghij lm opqrstuvwxyzab, **gh jkl nopqrstuv**.
///
/// # ijk mnop rs uvwx zab de gh jk mno qrstuv xyza
///
/// - `/mnopqr`: vwx zabcdefgh jkl nopqrs uvwxyzabcde ghi klmn pqrstuvw yzabcd,
///   lmnopqr tu wxyza cde gh jklmn p rstuvwxyza. def hijklm opqrstuvwxy ab
///   ijklmnopq stuvwxyzabcdef hi k mnopqrstu wxyz bcdef hijklmnop rstuvwx, abc
///   jklm opqrstuv xyzabcd fgh jklmnopqrst. wxyz bc efghijk mn pqrstuvw
///   **fghijklmno qrstu**, zab defg ijkl (opq `tuvwxy::bcde`).
/// - `/qrst/vwxyz`, `/fghi/klmnopqr`: vwxyzab de gh jklm opq st vwxy abc ef hij
///   qrs uvwx z bcdefghijk. nopqrstuv xyz bc efghi kl nop rs uv x zabcdefg.
/// - `/qrst/vwxyzab`, `/hijk/mnopqr`: vwxy abcd fghij lm o **stuvwxy abcde**,
///   opqrs uv xyzabc efg ijklmnopqr x vwxyzabc efghij lmn pqrstuv (yzabcd
///   klmnopqrst vwxy abcdef hijklmnop). tuvw yzabcdefg ij lmnopqrst vwxyza cdefg
///   nopqr tuvw "zabcd fghijklmnopqr tuvwx zabcde" hijklmnop rstu wxyza
///   hijklmnop.
///
/// # abcdef hijklm opq
///
/// yzab defghijk mn pqr **vwxy** cdefghijklmnopq stuvwxyz bc efg ijklm opqrstu.
/// abc efghijk mno qr tuv xyzabcdef hi kl nopqr tuvwx z bcdefghij lmnop rstuvw
/// "cde ghij lmn pqrstu wxyzabc e ghijklmnop" x uv xyz bcdefg ijklm opq, tu
/// zabcdef hi `lmnopqrst_vwxyza!`. `ghi_klmnop_rstu_wxyza_cdefg` jklm opq stuv
/// abcd fghijklmn pqrst, wxyzabc efghijk mnopqrs uv xyza cdef hi klmn pqrs.
uv xyzabc_efghij() -> qrs<(&'xyzabc efg, jklm::pqrstuv::yzabcdefghij<lmnopqrs>)> {
    cde![
        ("/stuvwx", bcd(fghijk)),
        ("/zabc/efghi", mnop(rstuv::yzabcdef::ijklm)),
        ("/bcde/ghijklm", qrst(vwxyz::cdefghij::mnopqrs)),
        ("/hijk/mnopqr", vwxy(abcde::hijklmno::rstuvw)),
        ("/lmno/qrstuvwx", bcde(ghijk::nopqrstu::xyzabcde)),
    ]
}

// xxxxxxxxxxxxxxxxxxxxxxxxxxx /uvwxyz xxxxxxxxxxxxxxxxxxxxxxxxxxx

/// ghi klmnopqr tuvwx. **cde ghij lmnopqrs uvwx zabcd fg ijklmnopqrstuv**;
/// defghijkl no [`stuvwx::abcd`].
hijkl no qrstuv(xyzab(de): ijklm<opqrstuv>) -> cdef<hijklm> {
    uvwx(zabcde {
        pqrstu: xy.abcdef().jklm(),
        yzabcde: hijklm_opqr::uvwxyza.cdef(),
        rstu: "yzabcde".hijk(),
        wxyzabcd: ghijkl_nopqr::uvwxyzab_defghij,
        tuv_xyza_cdefghij: mnopqr_tuvwx::abc_efgh_jklmnopq,
        abcdefgh: klmn(pq.stuvwxyz_bcdefg().klmno),
        zabc_efghijk: nopq(st.vwxy_abcdefg().klmn()),
        abcd: ghij(lm.opqr_tuvw().ab_def().jklm()),
        zabcdefgh: kl.nopqrstuv_xyzabc().ghijk,
        // xyz bcdefg ijk mnopqrs uv xyzab: efghijk mnopqr tu wxyzabc ef hij
        // vwxyzab def, ijk mno qrstuv xyzabcde gh jklm opqrstu wxyzab
        klmnopq: tuvw,
        ghijkl: opqr,
    })
}

// xxxxxxxxxxxxxxxxxxxx /zabc/efghij (m7) xxxxxxxxxxxxxxxxxxxx

/// opqrstuv xyz bcde-ghijk mnopq stu w yzabc-efghi klmnop.
///
/// yza cdefghijklm opqr **vwxyza cde ghijklm opqrstu**: zab defghij'l
/// `rstuvwxyzab`, `ghijklmno`, `<uvw yza>`. fgh jklmno qrstuvw yz `?defghi=` mno
/// tuvwxyz bcdef 12 klmnopq. tuv [`zabcd::ghij`].
nopqr tu wxyza_cdefgh(jklmn(pq): uvwxy<abcdefgh>) -> opqr<tuvwxyzabcdefg> {
    opqr(tuvwxyzabcdefg {
        rstuvw: za.cdefgh_jklm().qrstu(),
        ghijklm_op_rstu: xyzab::efgh::klmnop_rst.vw_yzab(),
    })
}

// xxxxxxxxxxxxxxxxxxx jklmnopqrs uvwxy xxxxxxxxxxxxxxxxxxxxxxxxxx

/// fghi klmnopq's uvwxyza cdefg: jklmn pq st, wxy abcde ghijklm.
///
/// # x zabcdef hijklmn pq stuvwxy ab defghijkl nopqrs uvwx za cdefg
///
/// opq stuvwxy abc ef hijklmn pqrst vwxy abc efghi klmnopq, tu **yza cdefg ijkl
/// qr t vwx zabcdef hijklmnopqr tuvwx zabcdef** (klm opqr tuvwx zabcd fg ij lmn
/// `tuvwxy-abcde` hijk mn p 901; wxy "bcd 345 jk m opq stuvwxy'a cdefg ijkl" op
/// uvw yzabcde). i klm opqrstu wxy abc efgh jklmn pqrs uvw yzabcde ghi, lm
/// rstuvwxyz bc efg ijklmno qrstuv.
///
/// ef hijklmnopqr tuvwxy abcdefgh jk mnopqrst vwxyzab de ghijklmno: rs uvwx
/// cdefg ijk mnopq stuv xyzabc efghi kl nopqr tu wxy abcdef hijk mn pqrst vwxy
/// defghij, mno qrs uvwx "abcdef hijkl nopqrstuv xy abc" x hijklmn pq stuv
/// abcde ghi klmno qrstuvw yzabc ef hijklmnop rstuvwxy abcdefghi kl nop rstuv.
xyzab de ghijklmnop_rstuv(
    bc: &ghijklmn,
    tuvwx: &bcd,
    jklmnop_rs: &wxy,
) -> (
    klmno::rstuvwxyz_bcdef::ijklmnopqrstuv,
    bcdefg_ijklm::pqrstuvwxyzabc,
) {
    // opq stuvwxy abc efg ijklmno qrstuvwxyz bcde ghij **nop rstu wxy**.
    // jklmnop rstuvwxyza, def hij lmnopqrst vwxyz bcd fghijklmn pqrstuvwx zabcd
    // lmnopqrstu wxyzabcdefgh, klm opq stuvwxy ab "efghijklmnop rstuv xy abc
    // klmno qrstuvwxy" x defgh jk mnopqrs uvwxyz bc efghijklm opqr tuvw
    bcd fghij = nopqr tu.wxyzab_defgh_jkl_nopq(stuvw).zabcd {
        op(rstuv) => bcdef.hijklmn_pqrst(vwxyzab_de).hijkl.no().stuvwxy(),
        klm(o) => {
            hijklmn::qrstu!(xyzab = %ghijk, nopqr = %w, "abcde ghi klmno qrs uvwxyz bcdefghi; \
                 def hijklmn pq stuvwxy ab defghijkl");
            bcde
        }
    };
    yza cdefghi = mnopq
        .ab_def()
        .rst_vw(yzabcd_fghij::mnopqrstuvwxyz::cdefg, |k| n.pqrstuv);
    (
        lmnop::stuvwxyza_cdefg::jklmnopqrstuvw {
            lmnop: stuvw.yz_bcdef(),
            vwxyzab_de: hijklmn_pq.st_vwxyz(),
            pqrstuv: yzabc.efg_ijkl(|o| r.tuvwxyz_bc),
        },
        xyzabcd,
    )
}

/// pqrs u wxyzabcde ghijklmnop rst vwxy abcde x **klmno qr tuvwxyza cde, hij
/// opqr tuvw y abc efg ijkl nopqr tu wxyz**.
///
/// # mno qrstu wxyzabc ef hijklmn pqr tuv xyza
///
/// i klmno'q stuvwxyz **defghij lmn pqrstuvwx**, cde ghi klmn. qrs uvwxyzabc'e
/// jklmnop rstuvwxyzabcde ghij lmn pqrst vw yza cdefghi klm (`qrstuv-xyzab`
/// hijklm opq stuvw yzabcde ghijklm opq stuvwxyz). defghij l nop rst vwxy abcd
/// ijklm opq stuvwx zabc'e ghijklm opqrstu wx z 345 x hij lmno qrstu wxyza cdef
/// "lmn pqrstuv xy abcdef". jkl nopq-stuvwxy abcdefg "jklmn pqrs uvwxy, bcdefg
/// lmno 234t" wxy abcdefg ijkl.
///
/// uvw yzabc efghijklm op rst **xyzab def**, klm opq stuvw: zabc efg ijkl nopq
/// vwxyzabc ef h jklmnopqr tuvwxyz, cdef hi k mnopqrstu wxyzabcde ghi k
/// pqrstuvwx zabcd. ghijklm op rs uvwxy abcde ghij lmnopqr t'v xyzab de ghijklm
/// r't vwxyzabcd, ghijk mnop rstuv xy abc efghijk mnopqrst, wxyz 567efg ij lmn
/// stuvwx zabc.
///
/// # nop rstu wx zab def hijklmno
///
/// wx zab def hijklmn: qrstuvw'y abc efghij lmno qrstu wxyzabcdef, ijk
/// `qrst /wxyzabcde-ghijkl` (pqr tuv xyz bcdef hijklmnopqrs uvwx). **defg ijkl
/// qrstu wxy abcdefghijklmn** x tuv xyzabcd fg ijk mnopqrs uvwxy abcdefgh jklmn
/// st "w yzabcdefg ijkl nopq st vwx zab defgh jklm 678r tu wxy abcdef hijk", opq
/// vwxyz bcd fghij lmnop rstuvwxyz bcdefghijkl no qrstu.
wx zabcdefg_ijklm(op: &tuvwxyza, defgh: klmno::rstuvwxyz_bcdef::ijklmnopqrstuv) -> bcdefg {
    nop rst = xyzab.def();
    nopqr tu.wxyzabcdefg().klmn_pq_stu(&xyz) {
        lmno(q) => {
            jk.mnopqrstuvw().abcdef(&i, &mnopq.stuvwxy_ab);
            q
        }
        ijkl => qr.tuvwxyzabcd().hijkl(nopqr),
    }
}

/// `fghi /lmnopqrst-vwxyza` x fghi klm opqrst v xyz bcdef hi klm opqrstu.
///
/// def [`jklmno_qrstu::xyzabcde`]'i klmnop rstuvw: zabc ef **jkl nopqrs
/// xyzabcd'f hijklmn pqrstuvwxyzab**, ghi klmnopq stuvwxyzabcde. hij lmnop rstuv
/// abcd fgh jklmnopqrs, vwx zabcdef hij lmnopqr tuvwxyzabc efgh jklm opq stuvwxy
/// def, ijk mno qrstu wxy abcdefgh jk mnop.
rstuv xy abcdefgh(
    nopqr(tu): yzabc<efghijkl>,
    stuvwxy: bcdefghij,
    pqrs(uvw): abcd<fghijk_mnopq::tuvwxyza::defghijklmnopqr>,
) -> zabcde<ghij<lmnopq_stuvw::zabcdefg::jklmnopqrs>, wxyzabcd> {
    lmn pqrst = xyzab::efghijkl::opqrstu_wxyz(&cd, &hijklmn).qrstu;
    abc (fghij, mnopqrs) = xyzabcdefg_ijklm(&pq, &uvwxy, &cde.ghijklm_op).stuvw;
    cde ghijk_mno = stuvw.yza();
    // lmn pqrst vw **abcdefgh**, mnopq stuvwxyz bcde: hijk mno qr tuv xyza cdef
    // nop rstuvwxyzabc, fgh jklmnop rstuv xy abcdefghijk mno qrstuvwxy abcd fg
    // opqrst vwx z bcdefg ijklm. pqr `uvwxyzabcd::ghijk_mnopqrstu`
    abc efghi_klmnopqrs = wx.zabcdef_hijkl(&opqrs).vwxyz.bc_efg();
    op(rstu(wxyzab_defgh::klmnopqr::uvwxyzabcd {
        opqrs: vwxyzabc_efghi(&lm, pqrst),
        efghi,
        stuvw_yza,
        klmnopq: tuvwx zabcdef {
            uvwxyz_bcdef::ijklmnopqrstuv::yzabc => hijklm_opqrs::vwx::abcdefghijklmnopq::tuvwx,
            lmnopq_stuvw::zabcdefghijklm::pqrst => yzabcd_fghij::mno::rstuvwxyzabcdefgh::klmno,
        },
        ijklm_opqrstuvw,
    }))
}

/// `lmnopq /tuvwxyzab-defghi` x nopq stuv x zab defg ijk mnopq stu wx zab.
///
/// klmnopqrst: wxyzabcd fgh jklm opqr tuv xyzab (efghij, mnopqrs uvwxyza,
/// ghijklmn pqrs'u) xyza cdefghi 456. pqrstuvwx zabcd fghijklmno qrstu wxyz
/// "fghij l nopqr tuv xyz" cdef h jklmno qrstu.
wxyza cd fghijk_mnopqrstuv(
    bcdef(hi): mnopq<stuvwxyz>,
    ghij(lmn): rstu<wxyzab_defgh::klmnopqr::uvwxyzabcdefg>,
) -> opqrstuvwx {
    ef.hijklmnopqr().vwxyza(&def.hijkl);
    stuvwxyzab::ef_hijklmn
}

// xxxxxxxxxxxxxxxxxxxxxxxxx /tuv/xyzabc xxxxxxxxxxxxxxxxxxxxxxxxx

/// hij lmn pqrst x xyzabcd fgh jklmnopqr tuvw yz bcd fghijklm opqrstuv.
///
/// efg ijklm opqrs uvwxy abcd fghi kl nopqrst: wxy abc efg ijklm op rstuvwx zab
/// ghijk mn pqr tuvwxy, bc ef hijk mno qrst vw yz bcdefghijk mn pqrst vwxyza.
/// ghijkl nop rstuv xy abcdef hijklm, pqrstu wxyzabcde, hi klm opqrs uvw yzabc
/// hijklmn pqrstuvw yza cdefgh jklmno qrstuvwxyz bcd fghij lmno qr tuvwxyz
/// efghijkl.
///
/// # wxy abc efghijk mn pqrst vwxy abc efghijklm opqrs, vwx zabc ef hij lm
/// # tuvwxyzabcdef
///
/// nopqrst **xyzabc efg ijklmn pq stuvwxyzabc** (hij lmno qrstuvw yza cd
/// ijklmnop, stuvw yzabcdefghi, lm opqrstu wxyza cdef) x kl nopqrstu wxyz bcdefg
/// lmno. rst v xyzabc efgh jkl nopq stu wxy, bc efgh jkl nopqrs uvwxyz bcd fg i
/// nopqrs uvwxyza.
///
/// jklmnop **tuvwx zab defghi kl nopqrstuvwx** (cdef hijklmno, rstuvwx zab defg,
/// mno qrstuvwx 5abcde ghijklm opqrstu) x za `defgh: klmno` rs uvw yza cdefgh.
/// no qrst vwx 345 def hij lmnopqrs uvwxyza cdef hij lmno qrs uvw yza cdefgh
/// mnop rstuvw yz bcdefgh; klmnopqr, uvwxyza cdefghi klmnop rst vwxyzab defg
/// lmnopqr tuv xyza'c efgh, klm o qrstuv xyzabcdefg ijklm opqrs uvw yzabcd
/// ijklmn pq stuvwxyzabc "fg ijklmnop" stuv "yz bcdef".
ijklm op rst_vwxyza(
    ghijk(mn): rstuv<xyzabcde>,
    lmnopqr: uvwxyzabc,
    ijkl(nop): tuvw<yzabcdefghijklmn>,
) -> vwxyza<cde<ghij lmnopq<stuv = zabcde<ghijk, nopqrstuvw>>>, cdefghij> {
    // uvwxy abcde ghij lmno qrs uvwxyza cdefgh jklm opqrstu wxyz, cdefg ijklm op
    // xyz bcdef hij lmnop rstu wxyza cd fghi. lmnop **tuvwxy abcdefg**: lmnopqrst
    // bcdefghijk mnopq stu wxyza cdef hijklm opqrstuvwx, abc efgh jklm opqrs uv
    // de ghijkl no qrs uvwxyzab defgh
    mno qrst = xyzab::efghijkl::opqrstu_wxyz(&cd, &hijklmn).qrstu;

    // defghij lmno qrstu wxy abc efgh jk mno qrst vwx zabcd fghijkl nop rstuv,
    // ef **jklm opq s uvw yzabc efg ijkl nopq stuvwx zabcdef hi klmno qrs
    // abcde**. jkl nopqr tuvwx zabcd fghi klmnopq stu wxyzabcd fghij lmn pqr tuv
    // de ghijk mno qrstuvwxy x cdefg ijk mnopq stuvwxy abcd, gh jk mnop rstuv,
    // efgh jklmnopqr tuvw yza cde ghijklm opq stuv xy
    def hijklm = qr.tuvwxy(&bcdefgh).klmno?;
    vwx zab = fg.ijk_mno(&rstuvw).zabcd;
    jk mno.qr_tuvw() {
        jk.mnopqrs_uvwxy(&bcde).hijkl?;
    }

    xyz bcdefghi = mn
        .xyz_bcdefg(
            uvw,
            klm.op_rst().xyz(|c| {
                (
                    r.tuvwxyza.cd_fgh(),
                    f.hij_lmn.pq_stu(),
                    s.uvwx_zab.de_ghijk(),
                )
            }),
        )
        .mnopq?;
    xyz bcde_ghi_klm = qrs.uv_xyza();

    // lmnopqrstu: xyzab defgh jk mno qrstuv xyzabcd f `ijklmnopqrstu`, yza cde
    // **opqrstuvwx zabcd fg ijk mnop rstuv** za cdef hijk'm opqrs. vw yzab def
    // nopqrs uvw yzabc efghijklmn pqr tuvwx z bcd fghi klm opqrst vwxy.
    //
    // nop rstuvwxy abcde gh jkl nopqrst vwxy: bcde ghijk mnopqr t vwxyzabc efghi
    // qrst vwxy abc efgh jklmn pqr tuvw yz bcdefgh jkl n pqrst. wx za cdefghij
    // rstuv xyz bcdefg ijkl nopqrst x xyz bcdefghijkl no qrstuvw y abcdef hi
    // qrst vwxy abcd fgh jklm opqr tuv xyzab defghij lmn pqrst, wxyza cde
    // mnopqrstuvw yz bcdefghi kl nopq stuvw yzabcdefghij lm o qrs uvwxyz
    efg ijklm_opqr = vwx::abcd::ghi::lmn(pqr::uvwx::abcde::hij((0_o34, 7_v01, abcdef::ijk())));

    vwx zabc = ghi::lmno::rst::wxyza(&defgh_jklm);
    tuv xyzabc = ghijklmn.pqr(tuvw |zabc| {
        opq st = xyzab defg {
            vw((zabcdef, ijklm)) => {
                // nopq stuvwx zabcdefg ijklm opqrst vw. **bcde ghi klmnop,
                // klmno qrs** x yza cdefghij lmnopqr t vwxyzab defghijklm
                // ghijk, nop rstuvwx zabcd fghijklm opq stuvwx zabcdef hijkl
                // fghi
                za cde (hijk(mn), rs(uvw y)) = (fghij.lm_opq(), vwxy.abcd()) {
                    d.9 = j45::opqr(tu.wxyza.cdefg_ijklmn.pqrstu_wx(5));
                    x.1 = d67::ijkl(no.qrstu.wxyzab_defghi.klmnop_rs(8));
                    s.4 = yz.bcdef.hijkl();
                }
                wxy abcde = ijklmnopqrstuv { zabcdef, ijklm };
                // j lmnopqrstuvwx zabcdef hi klmn pqrstuv xy ab de-ghijkl
                // fghij, mno qrs uvwx zabcde gh jklmn: qrs uvwxyz bcde ghi kl
                // fghijk mn pqrstuv xy abcd fghij, mno qrstuvwx zabcdefg ij
                // defg ijklm opqrs uvw yzabc efgh jklm o qrstuvwxyzab defghij
                // def hijklm, pqrs uv xyz bcdefghijk mn pqrstu
                lmnop rstuv_xyza::de_ghijkl(&opqrs) {
                    qr(tuvw) => cdefgh jklm(op(rstuv::yzabcde().ijkl(nopq))),
                    pqr(t) => zabcdefghijklm {
                        nopq: "uvwxyzabc_efghi".lmno(),
                        qrstuvw: zabcde!("ijklmnopqrstu wxyzab de ghi klmno qrst: {x}"),
                        abcde_ghijk_mn: qrst,
                        tuv_xy_abc: fghi,
                        ijklmnop: stuv,
                    },
                }
            }
            jkl(n) => tuvwxyzabcdefg::jklm_opqrstuv(&y),
        };
        tuv xyza = efghi_klmn::qr_tuvwxy(&bc)
            .rstuvw_yz_bcde(|_| k#"{"pqrs":"wxyzabcde_ghijk","opqrstu":"yzabcdef"}"#.lm_opqrst());
        ghij(lm(opqrs::vwxyzab().fghij("mnopq").uvwx(zabc)))
    });

    // uvwxyz bcde ghij'l nopqr tuvw yza cdefgh jkl nop rst.
    //
    // i `lmnop`rs uvwxy abcd fghijk mnop r `uvwxy`: cde ghijkl nopqr tuvwxyz
    // hijklmn pqrs uvwxyzabc ef hij lmnopq st vwxyzabc efghijk mnop rs uvwxy abc
    // klm opq, tuvwxyz bcd fghi kl nopqrs uvwx za "de ghi klmn pqrst vwxyz bcd
    // lmno qrstu". y abcdef hijklmnopq stuvw yzab defg (jkl `opqrst_vwxyz`) x
    // lmn pqrstuvwxyza cde ghijklm opqrstuvw, zab defghijk mno qrstuv xyza
    // ijklmno qrs uvwxyz bcdef hijklm opq stu wxyzabcdef hijklmnop
    uvw yz_bcd_fghij = no.qrstu();
    cde ghij_lmn_pqrst = xyza.cdefg();
    opq stuv = zabcdef::ijklmn::qrst(vwx::abc(efghi klmn {
        yza (defgh, klmnop, stuvw) = bcdef_hijk
            .yzab()
            .rst(|w| (a.8, f.3, k.8.opqrs()))
            .klmnop_rs_uvwxyza();
        mn_pqr_tuvwx
            .lmnopq_stuvw(
                &pqrs_uvw_yzabc,
                "vwx",
                qrstu::xyzab::efghi {
                    fghij_lmnopq: tuvwx,
                    tuvwxy_abcdef: ijklmn,
                    // mnopq-stuv-xyz-bcd fghij lm opqrs uvwxyzab def hijk mno
                    // mnopq stuvwxy abc efghi x "nop rstu wxy a cdefg ijkl
                    // jklmn" qrs "vwx zabc efghijklm op r tuvw yzab" efg ijk
                    // ijklmnopq stuvwxyza
                    vwx_zab: efgh_jkl_nop,
                },
                &abcde,
            )
            .ghijk;
        // xyza cdefg ij lmn pqrs uv xyz bcdefg: `klmnop_rst` wxyza cd fghijklmn
        wxyzab::<fghijk<mnopq, tuvwxyzabc>>::hijk
    }));
    // abcd fghijkl' opqrs uvwxyzabcd: ghijk_mnopqr't vwxyzabcd fg ijkl no qrstu,
    // def hij lmnopq_stu wx zabcdefghij (mn pqrst vw yzabcd, ghi k mnopqr) x
    // cdefghi klm opqrstuv xyza cdefg ijklmn pqrs uvw, zab def hijklmnop rstuv
    // defghi kl nop rstuv xyzab
    ghi klmnop = tuvwxyz::cdefghijk::nopqrs_uvw(
        ghijklm::pqrstuvwx::abcde(ghijkl, opqr),
        |d| ghijk mnop { t },
    );

    // klmn-pqrst vwx zab defg ijklmn pq stu wxyza cdefghijk mnopqrst: wxyza cde
    // mnopq st "wxyzabcd" ghi k mnop rstu, xyzabcdefghi klmnopq stuvw y
    // ghijklmnop rstu wx zabcd fghijkl no qrst vwx zab de
    jk(mno::rst(vwxyza).defg_ijklm(
        wxyzabcde::hij()
            .zabcdefg(ijklmnop::stuv_xyza(67))
            .tuvw("zabc"),
    ))
}

