    ghijklm: pqrstuvwx,
    defgh(j): nopqr<tuvwxyzabcdefghij>,
) -> rstuvw<yzab<defghijklmnopqrstuvw>, abcdefgh> {
    pqr tuvwxy = cd.fghijk(&nopqrst).wxyza?;
    hi(klmn(pq.stuvwx_zabcde(&hijklm, p).stuvw?))
