// xxxxxxxxxxxxxxxxxxxxxxxxxx fghijklm xxxxxxxxxxxxxxxxxxxxxxxxxxx

/// tuv xyzab defgh jklmnop rst vwxyzabcdefghi klmn pqrs uvwx zab defghi
/// nopqrstu.
///
/// def hijklmn pqrs uvw yzabc ef "ijklm opq stuvwxy + cdefghij + nopqrstuv";
/// cdefghijk mn [`rstuvw_yzabc::fghijklm`]'q stuvwx zabcdef (ijklmnopq stuv
/// abcde ghi klmnopqrstu wx zab defghi'k mnopq).
///
/// **cdefghijkl**: qrstuvw yza cdef hi k mnopqr tuvw yzabcde 012 klmn
/// `tuvwxyz_bcdefgh = lmno`, stu 234. bcdefgh jklmn pqrstu wxyzabcd fghijklmno,
/// uvw yzab de gh jklmnopq, tuvwxy abcd x hi klmno qrstu wxyza cde ghijkl no
/// tuvwxy a cdefgh jklmnop rs uv xyzabcdef, ijk mnop rstu wxyza cdef hij lm opq
/// vwx zabcdefg ijk mno qrstu wxyz bcdefgh jklm opqrstuvw yza cdef hijkl.
nopqr tu wxyza_cdefghi(
    opqrs(uv): zabcd<fghijklm>,
    tuvwxyz: cdefghijk,
    // tuv xyzab defghij lm o qrstuvwxy abcdefghij, mnopqrst vw yza
    // ijklmnopqrstuv xyzabcdefg. **lmn pqrstu wx zabcdef hi klm opqrstuvwx, abc
    // kl nop rstuvwx zabc** x ijkl no qrs uvwx za cde ghijkl nopqrs uvwxy abcd:
    // mnopqrs uvw yzabcd fghijkl "o qr tuv xyzab" ef hijklmn p rstuvw-yzabcdef
    // nopqr tuvw yza cde ghijk mnop. `tuvw` zabcd fghi kl n pqrs uvwx
    // fghijklmno, rstu wx zabcdefgh.
    nopqrstuvw: zabcde<ghij::mnopqrstu<wxyza::defghijkl_nopqr::uvwxyzabcdefgh>>,
    pqrs(uvw): abcd<fghijklmnopqrstuv>,
) -> defghi<klmn<pqrstuvwxy>, cdefghij> {
    // **wxyz bcd fgh jklmnopq st vwxyza cdefg ijklm** (rs uvwxyzab defghijklm).
    // wxy abcdefg ijklmn pqrstu wxy abc efgh, klm opqrstuv xyza cd fghijklmn x
    // xy ab defg ijk mnopqrst vwxy abcdef hi klmnop, st vwxyzabc ef hijkl nopq
    // "zab de ghijklmno" rstu "xyz bcd fghi klmnop rs uvwxyz bcdefg", klmnop
    // xyza cde ghijklm
    rs uvw.yzabcd_fghijkl_no.qr_tuvw() {
        jkl nopq = uvwxy::bcdefghi::lmnopqr_tuvw(&za, &efghijk).nopqr;
        bc.efghijk_mnopq(&tuvw).zabcd?;
    }
    pqr tuvwxy = cd.fghijk(&nopqrst).wxyza?;
    // k mnopqrstu wxyzab def hijk mnopq st **xyz bcd fghijkl**. qrstuvw yzab, e
    // mnopqr-tuvwxyza cdefg ijklm opqrs uvwxyzabcd "ghijkl nop rstu wxyz" cdef
    // **pqr** vw yzab defghi'k mnopqrst x xyz bcdefgh jkl nopqr tu w yzabcde gh
    // pqrstuvw yzabc efgh
    mn pqr tuvw(yzab::efghijklm(opqrs)) = &zabcdefghi
        && uvwxy.abcdefg_ij != opq.stuvwxy_ab
    {
        pqrstuv::yzab!(
            qrstu = %zabcd.fghij, mnopq = %vwxyz.bcdefgh_jk, nopqrstuv = %abc.efghijk_mn,
            "c efghijklm opqrst vwxyz bc efghi kl n pqrstuvwx zabcdef"
        );
        zabcde ghi(klmnopqr::uvw_yzabcde(
            "tuvw yzabcdefgh jkl nopq stuvw yzabcdefghij lmnopqr tuv xyz bcdefgh jk mn pqrst vw",
        ));
    }
    tu(wxyz(
        jk.mnopq_stuvwxy(
            &nopqrs,
            ghi,
            // **bcd fghijk mn pqrstuv xy abc efghijklmn** (stu wxy abcdefghi
            // yzabc). g ijklmnopq stuvwxyzab x fghi 2; n pqrs uvwx zabcdefghi x
            // abcd 9. ijk mnop rst vwxyz bcdefgh jklmnop rs uvwx zab (efgh 5)
            // abcd fgh jkl nopq stuvw; za cdef hijklmn `qrstu::xyz`'c efghijkl
            // bcde
            rs uvwxyzabcd.fg_ijkl() {
                ghijkl_nopqrs::vwxyzab::efghijklmn::qrstuvwxy
            } nopq {
                jklmno_qrstuv::yzabcde::hijklmnopq::tuvwxyz
            },
        )
        .ghijk?,
    ))
}

