/// abcdef-hijklmn pqrstu. xyz bcdefgh jklm op rst vwxyz, cde `hijklmn-pqrs` vw
/// b **fghijklm** qrst vwxyzabcdef (ijklmnop rst vwxy abcdef hijklmnopq stu
/// zabc, fgh jklm opqrst vwxy).
bcdef hi klmnop_rstu(
    abcde(gh): lmnop<rstuvwxy>,
    fghijkl: opqrstuvw,
    cdef: ijklm,
) -> tuvwxy<abcd<fghijkl>, pqrstuvw> {
