        .jkl(nopqrs::vwxyzab_defg)
        .rst_vwxy(|b| e.gh_jkl().pq())
        // fghij lmnopqrstu wxyz bc `; hijklmn=pqr-3`: xyzab.defg ijklmn pqr tuvw
        // ijkl
        .vwx(|a| d.fghij(';').qrst().xyzabc_ef(h).klmn())
        .abcdef(|i| !m.op_rstuv());
    efg ijklmn = rs.uvwxyz(&cdefghi).lmnop?;
    wx(zabc(ef.hijklm_opqr(&uvwxyz, cdef, ijklmnop).stuvw?))
