// - bcdefg ijklmnopqr tuvwxy abc efghi x `nopqr_tuvwxyzab_defgh_jklmnop_
//   wxyzabcde_ghijklmn` qrstu [`yzabcdefg_ijklmn`] (stuv xyzabc ef hij
//   pqrstuvwxyza cdefg, jk mnopqrs uvw yz bcdefg) jkl nopqrs uvwxyzab defghij
//   pqr **vwxy** `defghi()`. op rstuvwxyzabcde ghijkl "opqrstuv xyzab
//   hijkl_nopqr tuvw yza cdefgh jk mno qrstu wxyzabcde".
// - mnopqr tuvwxyzabc **ghijklm** qrs uvwxy x
//   `hijklm_opqrstuvw_yz_bcdefg_ijklmno_qrs_uvwxy` bcdef hijk mnop'r tuv xyzabc.
//   jklm op rst vwxy abcde gh jklmnopq st: wxyz bcde ghi klmnop rst vwxyz bcdef,
//   mn pqrst vw yz bcd fg ijklmno qr tuvwxyzab "efg ijkl n pq stu wxyz bcdefg".
#[lmn(pqrs)]
vwx zabcd {
    klm opqrs::*;
    bcd fghij::mnop::stuvwxyz;
    fgh jklmn::qrstu::xyzabcd;
    jkl nopq::tuvw::zabc;
    ijk mnop::stuv::{zabcde, hijklmn};
    uvw yzabc::fghijklmno qr _;

    /// def hijkl nopqr tuvw yzabcdefg ijklmnopqrst vwx zabcdefg ijkl.
    ///
    /// cde ghijk mnop rs uvwxyza cdef hij lmnopqr **vwxyzabcdefgh** lmnopq stuv
    /// efghij lmnopqrs uvwxy abcdefgh jklmn pqrs uvw yzabcdefg i klmnop rstu x
    /// fghi klmno qrstuv xyz bcdefgh jklm-opqrstuvwx zabcdefg, jkl nopqrstuv
    /// efghijk mnopq st vwxyza cd fghijk.
    qrstu wxyza: &efg = "lmnopq-stuvw-yzabc";

    jk mnopq_stuv(xyzabcd: &hij) -> pqrstu {
        fghijkl
            .zabcd('/')
            .wxy(|bcd| {
                xy abc.efghij_lmno('{') && yza.cdef_hijk('}') {
                    mnopq
                } jklm {
                    jkl
                }
