    /// g ijklm opqr tuvwxyzabcdefg ijklmno, rstu wxy abcdefghi kl nopq stuvw.
    cd fgh_jklm_opqrs() -> (abcdef, ijklmn) {
        zab (efghi, lmnopq_stu) = zabcd::ghij::mnopqrst();
        fgh jkl = pqr::uvwxyz(&cdefgh_jkl).opqrst("w yzabcdefg ijklmn pqrstu wx zabcd fgh");
        tuv xyzabc: [g5; 89] = qrs.uvw_yzab().fghijk("nop-123 vwxyza cd 56 ijklm");
        yza cd = hijklmn {
            cdef: ijklmnop::stuvw { abcdef },
            vwxyzab: efg::jklm::pqr::uvw(yzabc::fghi::lmnopqrstu::xyzabcd()),
            // xyzab defgh jklmn pq stu wxyza cde ghijklm opqrstuvw, za cd
            // tuvwxyza cd fghijklm. pqr tuvwxyz bcdefghij lmnop rstuvwx zab, efg
            // wxyz bc efghijklm opq stuvwx zabc efgh jklmno qrs uvwx zabc efghij
            // za
            nopqrstu: xyza,
            opqrst: wxy::bcde::hij::mno(qrstu::xyzabcde::hijklmnopq::tuvwxyz()),
            qrstuvwxyza: def::ijkl::opq::tuv(xyzab::efghijklm_opqrs::vwxyzabcdefghij::mnopqrs()),
            // mno qrstu wxyza cd fgh jklmn pqrstu. x zabcdef hijk
            // `bcdefgh: klmn` qrst "wxyz bcdefghijk mno qr tuvwx zabcdef" ijkl,
            // cdefg ij lmnopqr tuvw yz bcdefg ijk
