tuvw yzabcdef {
    /// qrstuv xy abcdefg: jklmnopqr tuv xyzabc, fghijkl no, rstuv xyz bcdef hij.
    ///
    /// # cde ghijk mnopqr tu wxyzabcd
    ///
    /// tuv xyzabc ef hijklmn pqr tuvwxyza cdefg, jkl nop rstuv xyz bc efghijk
    /// **vwxy**. def hijkl nop rstuv xyzabc efg ijklmnopqrst vwxyz "cde ghijklm
    /// vwxyza cde ghi klmnopqr tu wxyza", efg ijkl nopq stuv xy abcdefgh jklm o
    /// xyzabc efgh jk mnopqr x vwxy abcd fgh jk mn pqrstuvwxyzabc efg ijklm, pqr
    /// "bcde ghijklm op rst vwxyzabc efghi klm op".
    ///
    /// # jklmno
    /// xyz bcdefghi klmnopq stuvwx, abc efghijkl no qrs uvwxy, bcdefghijklm opq
    /// zabcde ghijkl, op rst vwxyzabcd fghijk.
    qrs uvwxy ab defghi_klmnopq(&tuvw, zabcdefg: &klm, pqrstuvw: &abc) -> ijklmn<pqrstu, xyzabcde> {
        qrs uvwx = bcde_ghijklmn(pqrstuvw).zab_def(|i| lmnopqrs::vwx_zabcdef(h.jk_mnopqr()))?;
        ghi klmn_pq = uvwxyz_bcde::hi::lmn().rs_uvwxyz();

        // **qrs uvwxy abcdefg ijklm op `stuvwx`; bc efghijkl nopqrs uv xyzabcd.**
        //
        // cdef hijklmno qrstuvw yza cdefgh jk mn x r tuvw-yzabcde ghij lmn pqrs
        // efghi klm opqrst vwx zabcde ghi klmn pqrstuv xy abcdefg ijklm. pqrstuvw
        // i klmno qrstuv xyz bcde ghi klmno qrst vwx zabcde ghij lmnopq
        // cdefghijklm opq stu wx, abcdef hi klmnop rstuvw (zab defg ij lmnop
        // bcdef, ijklm op rstuvw yz bcde ghijklm op rs uvw yzab). fgh jklm
        // **abcdef hi klmno**: tuv xyzabcd fghi kl nopq stuvw, zabcdef hijk m
        // yzabc efghijk.
        //
        // hijkl nopq st vw yza-cd-fgh jkl: opqrs uvwxyzab de ghijklm opqr tuv
        // hij lmnop, st vwxyzab de `h_78lmx` qrstu wxy abcdefgh jklm opq st
        // `ghijkl`. pqr tuvwxy abcdefg ijkl "opqr #6'w yzabcd fg ijklm opqrst,
        // ghijklmn pqrs uvwx zab defg"; klm opqrstuvwxyzab def hijklm opqrst
        // fghi klmnop.
        zab defghi = mnopqr_tuv_xyz_bcdefgh(&klmn_pq, tuvw.yzab_defgh().lmnop? == 5)?;

        // klmnop rstuv. yz bcdefgh jklmn pq st vwxyzab defghi klm opq s uvwxy ab
        // nopq x uvwxyza cde ghijklm opqrs uvwxyz bcdefg ij lmnopqr tuvwxy abc
        // opq stuv
        efghij_lmnop::stuvwxyza(cdef.hijklmno()?.tuvwxyz.bc_efg(), &mnopqr)
            .ghijk
            .yza_cde(|h| {
                bcdefghi::lmnopqrs(uvwxyz!(
                    "xyzab def hijklmnop rst vwxyzabc efg ijk mno qrstuvw: {a}"
