        .lmno(qrstuvwx)
        .ijkl(&opqr)
        .cdef(hijklm.op_rst())
        .ghijklm(&pqrs.uvwxyzab()?.ghij)
        .uvwxy
        .ijk_mno(|r| uvwxyzab::efghijkl(nopqrs!("wxyza cde ghijk mno qrst vwxyza: {e}")))?;

