            // rst vwxyza cde ghijklm opq stu wxyzabc efg ijk mno qrstuvw.
            // nopq st vwxyza cdef hijklmn pq stuvwx x bc efghijklm opqrst
            // jklmnopq stu wxyzabc efghijk, nop rst vwxy abcdefghijkl nopq stu
            // klmn pqrstuvw yzabc efghij lmn pqrstuv xyz
            mno _ = uvwx.zabcdefg()?.lmnopqr.tu_wxy().cdef_hijklm(&pqrstu).xyzab;
