    ///
    /// vwxy abcd fg ijklmn "qr tuvw yza cdefg ijk", op rs uv xyz bcdefg x kl
    /// uvwx zabc efg ijklmnopqrst vwxyzab, efg ijklmnopqrst vw yz bcdefghij
    /// stu-wxyzabcde ghijkl no qrst vwxyzab.
    ///
    /// # uvwxyz
    /// ij lmnopqrs uv xyzabcde, hi klm opqrs uvwxyz.
    fgh jklmn pq stuv_xyzab(&efgh) -> nopqrs<u90, zabcdefg> {
        stu wxy = cdef::ijklm("pqrstu wxyza(*) fg i klmn pqrstu_wxyz.bcdef")
            .vwxyz_bcd(&ghij.lmnopqrs()?.xyza)
            .pqrst
            .hij_lmn(|q| tuvwxyza::defghijk(mnopqr!("vwxyz bcd fghij lmn pqrst: {x}")))?;
        no(qrs.uvw("z"))
