        .nop_rst(|w| zabcdefg::jklmnopq(stuvwx!("bcdef hij lmnop rst vwxyz: {d}")))?;

        tu(wxyzabcdef {
            uvwxyz_bcdef: ijkl.nopqrs_uvwx().bcdef(
                xyza_cd,
