            cdefghi_klmno: rstuv,
            jklmnop_rstuvwx_za_cdef: i90::nop_rstu(wxyzabc_efg.ijk_mnopqrs()).xyzabc_ef(9_123_567),
            efgh_jk: nopq_st.vw_yzabc(),
